    # [프로그램 - 언어설정] 현재 선택된 언어에 맞게 화면의 모든 UI 텍스트를 변경
    def apply_language(self):

        lang = self.current_language

        for widget in self.findChildren(QWidget):
            class_name = widget.metaObject().className()
            object_name = widget.objectName()

            if not object_name:
                continue
            
            if isinstance(widget, QTabWidget):
                for i in range(widget.count()):
                    tab_page = widget.widget(i)

                    if tab_page is None:
                        continue

                    tab_name = tab_page.objectName()   
                    text = tr(lang, tab_name)
                    if text == tab_name:
                        continue

                    widget.setTabText(i, text)

            if isinstance(widget, QToolBox):
                for i in range(widget.count()):
                    page = widget.widget(i)

                    if page is None:
                        continue

                    page_name = page.objectName()
                    text = tr(lang, page_name)
                    if text == page_name:
                        continue

                    widget.setItemText(i, text)

            if isinstance(widget, QPushButton):
                button_name = widget.objectName()

                if not button_name:
                    continue

                text = tr(lang, button_name)
                if text == button_name:
                    continue

                widget.setText(text)

            if isinstance(widget, QGroupBox):
                groupbox_name = widget.objectName()

                if not groupbox_name:
                    continue

                text = tr(lang, groupbox_name)    
                if text == groupbox_name:
                    continue

                widget.setTitle(text)

            if isinstance(widget, QCheckBox):
                checkbox_name = widget.objectName()

                if not checkbox_name:
                    continue

                text = tr(lang, checkbox_name)
                if text == checkbox_name:
                    continue

                widget.setText(text)

            if isinstance(widget, QRadioButton):
                radio_name = widget.objectName()

                if not radio_name:
                    continue

                text = tr(lang, radio_name)
                if text == radio_name:
                    continue

                widget.setText(text)

            if isinstance(widget, QLabel):
                label_name = widget.objectName()

                if not label_name:
                    continue

                text = tr(lang, label_name)
                if text == label_name:
                    continue

                widget.setText(text)            
            
            for combo in [
                getattr(self, "combo_tblspace", None),
                getattr(self, "combo_obs_dblist", None),
                getattr(self, "combo_api_obsId", None),
                getattr(self, "combo_mksce_sfmName", None),
            ]:
                if combo is not None and hasattr(combo, "set_language"):
                    combo.set_language(lang)

            # 데이터셋 생성 화면 ButtonComboBox 언어 변경
            for combo in getattr(self, "combo_boxes", {}).values():
                if combo is not None and hasattr(combo, "set_language"):
                    combo.set_language(lang)

            # 일반 QComboBox의 Please select 항목 언어 변경
            for combo in [
                getattr(self, "cb_searchTable", None),
                getattr(self, "cb_apiObsType", None),
                getattr(self, "cb_dataTable", None),
            ]:
                if combo is None:
                    continue

                old_select_texts = [
                    "Please select",
                    tr("en", "common_please_select"),
                    tr("ko", "common_please_select")
                ]

                current_index = combo.currentIndex()

                for i in range(combo.count()):
                    if combo.itemText(i).strip() in old_select_texts:
                        combo.setItemText(i, tr(lang, "common_please_select"))

                if current_index >= 0:
                    combo.setCurrentIndex(current_index)

            
            # DB 테이블 목록 한글/영문 변경
            self.translate_db_table_combos(lang)

            # API 자료 유형 콤보박스 한글/영문 변경
            self.translate_api_obs_type_combo(lang)

            # 데이터셋 화면 자료유형 콤보박스 항목 언어 변경
