    # [프로그램 - 언어설정] 현재 언어에 맞는 "선택하세요" 문구 반환
    def select_text(self):
        return tr(self.current_language, "common_please_select")

    # [프로그램 - 언어설정] DB 테이블 콤보박스 표시 언어 변경
    def translate_db_table_combos(self, lang):
        for combo in [
            getattr(self, "cb_searchTable", None),
            getattr(self, "cb_dataTable", None),
            getattr(self, "cb_apiObsType", None),
        ]:
            if combo is None:
                continue

            current_table_name = combo.currentData()
            current_index = combo.currentIndex()

            combo.blockSignals(True)

            for index in range(combo.count()):
                table_name = combo.itemData(index)

                # 첫 번째 '선택하세요' 항목
                if table_name is None:
                    combo.setItemText(
                        index,
                        tr(lang, "common_please_select")
                    )
                else:
                    combo.setItemText(
                        index,
                        self.get_db_table_display_name(
                            table_name,
                            lang
                        )
                    )

            # 기존에 선택했던 실제 테이블 유지
            selected_index = combo.findData(current_table_name)

            if selected_index >= 0:
                combo.setCurrentIndex(selected_index)
            elif current_index >= 0:
                combo.setCurrentIndex(current_index)

            combo.blockSignals(False)

    # [API 자료수집] 자료 유형별 화면 표시명 반환
    def get_api_obs_type_display_name(self, obs_type, lang=None):
        lang = lang or self.current_language

        type_names = {
            "waterlevel": {
                "ko": "수위",
                "en": "WaterLevel"
            },
            "rainfall": {
                "ko": "강우",
                "en": "Rainfall"
            },
            "discharge": {
                "ko": "유량",
                "en": "Discharge"
            },
            "daminlet": {
                "ko": "댐 유입량",
                "en": "DamInflow"
            },
            "damrelease": {
                "ko": "댐 방류량",
                "en": "DamOutflow"
            },
            "tidelevel": {
                "ko": "조위",
                "en": "TideLevel"
            },
        }

        type_info = type_names.get(str(obs_type).strip())

        if type_info is None:
            return str(obs_type)

        return type_info.get(lang, type_info["en"])

    # [프로그램 - 언어설정] API 자료 유형 표시 언어 변경
    def translate_api_obs_type_combo(self, lang):
        combo = getattr(self, "cb_apiObsType", None)

        if combo is None:
            return

        # 현재 선택된 실제 자료 유형 저장
        current_obs_type = combo.currentData()

        combo.blockSignals(True)

        for index in range(combo.count()):
            obs_type = combo.itemData(index)

            # 선택하세요 항목
            if obs_type is None:
                combo.setItemText(
                    index,
                    tr(lang, "common_please_select")
                )
            else:
                combo.setItemText(
                    index,
                    self.get_api_obs_type_display_name(
                        obs_type,
                        lang
                    )
                )

        # 언어 변경 전 선택된 자료 유형 유지
        selected_index = combo.findData(current_obs_type)

        if selected_index >= 0:
            combo.setCurrentIndex(selected_index)
        else:
            combo.setCurrentIndex(0)

        combo.blockSignals(False)

    # [데이터조회] DB 테이블의 실제 이름에 해당하는 화면 표시명 반환
    def get_db_table_display_name(self, table_name, lang=None):
        lang = lang or self.current_language

        table_names = { 
            "waterlevel": {
                "ko": "수위",
                "en": "WaterLevel"
            },
            "rainfall": {
                "ko": "강우",
                "en": "Rainfall"
            },
            "discharge": {
                "ko": "유량",
                "en": "Discharge"
            },
            "daminlet": {
                "ko": "댐 유입량",
                "en": "DamInflow"
            },
            "damrelease": {
                "ko": "댐 방류량",
                "en": "DamOutflow"
            },
            "tidelevel": {
                "ko": "조위",
                "en": "TideLevel"
            },
            "watershed": {
                "ko": "유역평균강우",
                "en": "WatershedAverageRainfall"
            },
            "predict_rain": {
                "ko": "예측강우",
                "en": "PredictedRainfall"
            }
        }

        table_info = table_names.get(str(table_name).strip())

        if table_info is None:
            # 등록되지 않은 테이블은 실제 테이블명 표시
            return str(table_name)

        return table_info.get(lang, table_info["en"])

    # [PerformanceCheck_Tab] 성능분석 옵션 콤보박스의 표시 언어 변경
    def translate_perform_option_combo(self, lang):
        combo = self.cb_perform_option
        current_index = combo.currentIndex()

        combo.blockSignals(True)
        combo.clear()

        combo.addItem(tr(lang, "perform_option_peak_waterlevel"))
        combo.addItem(tr(lang, "perform_option_peak_rainfall"))

        if 0 <= current_index < combo.count():
            combo.setCurrentIndex(current_index)
        else:
            combo.setCurrentIndex(0)

        combo.blockSignals(False)

    # [프로그램 - 언어설정] 전달받은 문구가 한글 또는 영문의 "선택하세요" 문구인지 확인
    def is_select_text(self, text):
        return str(text).strip() in [
            "Please select",
            tr("en", "common_please_select"),
            tr("ko", "common_please_select")
        ]
    
    # [프로그램 - 언어설정] 정보 안내 메시지 박스 표시 : message_key에 해당하는 다국어 메시지를 현재 언어로 변환하여 출력
    def show_info(self, message_key):
        QMessageBox.information(
            self,
            tr(self.current_language, "msg_info"),
            tr(self.current_language, message_key)
        )

    # [프로그램 - 언어설정] 경고 메시지 박스 표시 : message_key에 해당하는 다국어 메시지를 현재 언어로 변환하여 출력
    def show_warning(self, message_key):
        QMessageBox.warning(
            self,
            tr(self.current_language, "msg_warning"),
            tr(self.current_language, message_key)
        )

    # [프로그램 - 언어설정] 오류 메시지 박스 표시 : message_key에 해당하는 다국어 메시지를 현재 언어로 변환하여 출력
    def show_error(self, message_key):
        QMessageBox.critical(
            self,
            tr(self.current_language, "msg_error"),
            tr(self.current_language, message_key)
        )

    # [프로그램 - 언어설정] 언어 선택 콤보박스의 값이 변경될 때 호출 - 선택된 언어 코드를 저장하고 화면의 모든 UI 문구를 갱신
    def on_language_changed(self, index=None):
        language = self.cb_language.currentData()
        if language not in ('ko', 'en'):
            return

        self.current_language = language
        self._save_general_config()
        self.apply_language()   
        self.update_search_data_graph_language(language)
    

