    # [프로그램] 화면 표시 후 초기 로딩 작업 수행
    def _run_post_init_tasks(self):
        try:
            self.load_pyConsole()
        except Exception as e:
            print(
                tr(self.current_language, "error_load_python_console").format(
                    error=e
                )
            )

        try:
            self.init_databaseDate()
        except Exception as e:
            print(
                tr(self.current_language, "error_init_database_date").format(
                    error=e
                )
            )

        try:
            self.load_shapefiles()
        except Exception as e:
            print(
                tr(self.current_language, "error_load_shapefiles").format(
                    error=e
                )
            )
       
    # [프로그램] 종료 이벤트
    def closeEvent(self, event):        

        reply = QMessageBox.question(
            self,
            'KICT FLOOD AI',
            tr(self.current_language, "msg_closeEvent"),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No
        )

        if reply == QMessageBox.Yes:

            # save_config
            self.close_plugin()

            # clear_import_thread
            try:
                self.data_importer = getattr(self, "data_importer", None)  
                if self.data_importer is not None and self.data_importer.isRunning():
                    self.data_importer.stop()
                    self.data_importer.wait()
            except Exception as e:
                print(tr(self.current_language, "error_terminate_db_import_thread").format(error=e))

            # clear_search_item_combo
            for combo in self.combo_boxes.values():
                combo.cleanupFilter() 

            # clear_dataset_thread
            try:
                if hasattr(self, 'threadpool') and self.threadpool is not None:
                    self.threadpool.waitForDone()
            except Exception as e:
                print(tr(self.current_language, "error_wait_dataset_threadpool").format(error=e))
            
            event.accept()
        else:
            event.ignore()

    # [프로그램] 종료 전 리소스 정리
    def _cleanup_before_close(self):

        # 실시간예측 수행중일 경우 종료 시도
        if threading.active_count() > 1:
            try:
                myThread.cancel()
            except Exception:
                pass

        # DB import thread 정리
        try:
            self.data_importer = getattr(self, "data_importer", None)
            if self.data_importer is not None and self.data_importer.isRunning():
                self.data_importer.stop()
                self.data_importer.wait()
        except Exception as e:
            print("Failed to terminate DB Import Thread :", e)

        # clear_search_item_combo
        try:
            for combo in self.combo_boxes.values():
                combo.cleanupFilter()
        except Exception as e:
            print("Failed to cleanup combo filters :", e)

        # clear_dataset_thread
        try:
            if hasattr(self, 'threadpool') and self.threadpool is not None:
                self.threadpool.waitForDone()
        except Exception as e:
            print("Failed to wait for dataset threadpool:", e)

        # 대시보드창 종료
        try:
            if self.dashBoard and self.dashBoard.isVisible():
                self.dashBoard.close()
        except Exception as e:
            print("Failed to close dashboard :", e)

        # Performance timer 정리
        try:
            timer = getattr(self, 'perform_detail_timer', None)
            if timer is not None:
                timer.stop()
        except Exception as e:
            print("Failed to stop performance timer :", e)

        # Matplotlib 이벤트 disconnect
        try:
            canvas = getattr(self, 'basic_canvas', None)
            cids = getattr(self, 'perform_overview_cids', [])
            if canvas is not None:
                for cid in cids:
                    try:
                        canvas.mpl_disconnect(cid)
                    except Exception:
                        pass
            self.perform_overview_cids = []
        except Exception as e:
            print("Failed to disconnect matplotlib events :", e)

        # QWebEngineView 임시 html 파일 정리
        try:
            temp_html_path = getattr(self, 'temp_html_path', '')
            if temp_html_path and os.path.exists(temp_html_path):
                os.remove(temp_html_path)
        except Exception as e:
            print("Failed to remove temp html file :", e)

    # KICT-FLOOD-AI Plugin 화면 종료 전 CONFIG 설정
    def close_plugin(self):                      

        # 종료 전 리소스 정리
        self._cleanup_before_close()

        # config 저장
        self._save_general_config_to_parser()
        self._save_dashboard_config()
        self._save_shapefile_config()
        self._save_tablespace_config()
        self._save_model_env_config()
        self._save_sfmparam_config()
        self._write_config_file()

    # init : 데이터베이스 정보 가져오기
    def init_databaseDate(self):     
        
        conn = None

        try:
            # 기간설정정보 가져오기
            self.db_config["database"] = self.db_tablespace
            conn = mariadb.connect(**self.db_config)        
            cur = conn.cursor()

            # 데이터베이스 내 테이블 목록 가져오기
            select_query = "SHOW tables"
            cur.execute(select_query)
            resultset = cur.fetchall()
            self.cb_dataTable.clear()
            self.cb_searchTable.clear()
            self.cb_apiObsType.clear()
            
            # 선택 항목
            self.cb_dataTable.addItem(self.select_text(),None)
            self.cb_searchTable.addItem(self.select_text(),None)
            self.cb_apiObsType.addItem(self.select_text(),None)

            for row in resultset:
                table_name = str(row[0]).strip()

                # 데이터 관리용 테이블 목록
                # 화면에는 번역명을 표시하고 실제 테이블명은 itemData에 저장한다.
                self.cb_dataTable.addItem(self.get_db_table_display_name(table_name),table_name)

                # 데이터 조회용 테이블 목록
                # 예측강우 테이블은 관측자료 조회 목록에서 제외한다.
                if table_name != "predict_rain":
                    self.cb_searchTable.addItem(self.get_db_table_display_name(table_name),table_name)

                # API데이터 조회용 테이블 목록
                # 예측강우 테이블은 관측자료 조회 목록에서 제외한다.
                if (table_name != "predict_rain") and (table_name != "watershed"):
                    self.cb_apiObsType.addItem(self.get_db_table_display_name(table_name),table_name)

            # 컨트롤 날짜데이터 셋팅
            self.cb_dataset_startYear.clear()
            self.cb_dataset_endYear.clear()

            # 현재 연도
            current_year = datetime.now().year

            # 1. 최소 연도 조회
            sql_min = "SELECT YEAR(dt_date) AS year FROM waterlevel ORDER BY dt_date ASC LIMIT 1;"
            cur.execute(sql_min)
            result_min = cur.fetchone()
            min_year = result_min[0] if result_min else 2011  

            # 2. 최대 연도 조회
            sql_max = "SELECT YEAR(dt_date) AS year FROM waterlevel ORDER BY dt_date DESC LIMIT 1;"
            cur.execute(sql_max)
            result_max = cur.fetchone()
            max_year = result_max[0] if result_max else current_year  

            # 3. 콤보박스에 연도 채우기
            for year in range(min_year, max_year + 1):
                self.cb_dataset_startYear.addItem(str(year))
                self.cb_dataset_endYear.addItem(str(year))

            self.sp_ds_preProcessing_startMonth.clear()
            self.sp_ds_preProcessing_endMonth.clear()
            for idx in range(1,13,1):
                self.sp_ds_preProcessing_startMonth.addItem(str(idx))
                self.sp_ds_preProcessing_endMonth.addItem(str(idx))
            
        except mariadb.Error as e:
            print(f"init databaseDate Error Occurred : {e}")
        except Exception as e:
            print(f"[Unknown Error] {e}")
        finally:
            if conn:
                conn.close()

    # init : QGIS ShapeFILE 불러오기
    def load_shapefiles(self):      
        self._load_shapefile_layers_and_controls()

