    # 데이터셋 컬럼 자료 유형 콤보박스를 현재 언어로 초기화 (표준화자료/결측치보정/이상치보정)
    def init_dataset_column_type_combos(self):
        item_keys = [
            "combo_item_normalized_data",
            "combo_item_missing_value_correction",
            "combo_item_outlier_filtered_data",
        ]

        for combo_name in self.get_dataset_column_type_combo_names():
            combo = getattr(self, combo_name, None)

            if combo is None:
                continue

            current_index = combo.currentIndex()

            combo.blockSignals(True)
            combo.clear()

            for key in item_keys:
                combo.addItem(tr(self.current_language, key))

            if 0 <= current_index < combo.count():
                combo.setCurrentIndex(current_index)
            else:
                combo.setCurrentIndex(0)

            combo.blockSignals(False)

    # 언어 변경 시 데이터셋 컬럼 자료 유형 콤보박스의 항목을 갱신
    # 기존 선택 인덱스는 유지하고, 모든 항목을 전달받은 언어로 다시 생성한다.
    def translate_dataset_column_type_combos(self, lang):
        item_keys = [
            "combo_item_normalized_data",
            "combo_item_missing_value_correction",
            "combo_item_outlier_filtered_data",
        ]

        for combo_name in self.get_dataset_column_type_combo_names():
            combo = getattr(self, combo_name, None)

            if combo is None:
                continue

            current_index = combo.currentIndex()

            combo.blockSignals(True)

            # 항목 개수가 부족하거나 기존 텍스트가 깨져 있어도 항상 3개로 재초기화
            combo.clear()
            for key in item_keys:
                combo.addItem(tr(lang, key))

            if 0 <= current_index < combo.count():
                combo.setCurrentIndex(current_index)
            else:
                combo.setCurrentIndex(0)

            combo.blockSignals(False)

    # 언어 변경 시 데이터셋 Timeseries 시간간격 형태 콤보박스의 항목을 갱신
    def init_leadtime_unit_combo(self, lang):
        current_index = self.cb_ds_leadtimeUnit.currentIndex()

        self.cb_ds_leadtimeUnit.blockSignals(True)
        self.cb_ds_leadtimeUnit.clear()

        # 화면 표시 문자열과 코드에서 사용할 고정값을 분리
        self.cb_ds_leadtimeUnit.addItem(
            tr(lang, "combo_item_hours"),
            "hours"
        )
        self.cb_ds_leadtimeUnit.addItem(
            tr(lang, "combo_item_minutes"),
            "minutes"
        )

        index = current_index
        self.cb_ds_leadtimeUnit.setCurrentIndex(
            index if index >= 0 else 0
        )

        self.cb_ds_leadtimeUnit.blockSignals(False)

        # 언어 변경 중에는 콤보박스 신호를 차단하므로
        # 현재 선택된 단위에 맞게 오른쪽 간격 문구를 직접 변경
        current_unit = self.cb_ds_leadtimeUnit.currentData()

        if current_unit == "hours":
            self.lbl_ds_leadtimeTerm.setText(
                tr(lang, "label_hour_interval")
            )
        elif current_unit == "minutes":
            self.lbl_ds_leadtimeTerm.setText(
                tr(lang, "label_minute_interval")
            )
        else:
            self.lbl_ds_leadtimeTerm.setText("")
    
    # init : QGIS 레이어 추가
    def add_mapLayer(self, lyr, lyrName, etc, color, labelText, shapes):

        addLayer = QgsVectorLayer(lyr, lyrName, etc)
        if not addLayer.isValid():
            print ("Layer failed to load!")
        else:
            # 같은 레이어가 있다면 지우고 다시 추가한다.
            for layer in QgsProject.instance().mapLayers().values():
                if layer.name() == lyrName:
                    QgsProject.instance().removeMapLayers([layer.id()])

            # 레이어 타입(point, polygon)에 따라 렌더링
            layer_type = addLayer.geometryType()
            if layer_type  == QgsWkbTypes.PointGeometry:
                QgsProject.instance().addMapLayer(addLayer)
                # set labeling
                text_format = QgsTextFormat()
                buffer_settings = QgsTextBufferSettings()
                buffer_settings.setEnabled(True)
                buffer_settings.setSize(0.10)
                buffer_settings.setColor(QColor(color))
                text_format.setBuffer(buffer_settings)
                label = QgsPalLayerSettings()
                label.fieldName = labelText
                label.enabled = True
                label.setFormat(text_format)
                labeler = QgsVectorLayerSimpleLabeling(label)
                addLayer.setLabelsEnabled(True)
                addLayer.setLabeling(labeler)
                # set symbol
                addLayer.renderer().symbol().symbolLayer(0).setSize(2)
                props = addLayer.renderer().symbol().symbolLayer(0).properties()
                props['color'] = color
                props['name'] = shapes
                addLayer.renderer().setSymbol(QgsMarkerSymbol.createSimple(props))
                # qgis symbol refresh
                iface.layerTreeView().refreshLayerSymbology(addLayer.id())
                # repaint
                addLayer.triggerRepaint()                
                print(
                    tr(self.current_language, "msg_layer_loaded").format(
                        layer_name=lyrName
                    )
                )
            elif layer_type  == QgsWkbTypes.PolygonGeometry:
                QgsProject.instance().addMapLayer(addLayer)
                # set labeling
                text_format = QgsTextFormat()
                buffer_settings = QgsTextBufferSettings()
                buffer_settings.setEnabled(True)
                buffer_settings.setSize(0.10)
                buffer_settings.setColor(QColor('black'))
                text_format.setBuffer(buffer_settings)
                label = QgsPalLayerSettings()
                label.fieldName = labelText
                label.enabled = True
                label.setFormat(text_format)
                labeler = QgsVectorLayerSimpleLabeling(label)
                # set symbol
                props = addLayer.renderer().symbol().symbolLayer(0).properties()
                props['color'] = color
                if (lyrName == 'rivernetwork'):
                    addLayer.setOpacity(0.8)
                    addLayer.setLabelsEnabled(False)
                if (lyrName == 'watershed'):
                    addLayer.setLabelsEnabled(True)
                    addLayer.setLabeling(labeler)
                addLayer.renderer().setSymbol(QgsFillSymbol.createSimple(props))
                # repaint
                iface.layerTreeView().refreshLayerSymbology(addLayer.id())
                addLayer.triggerRepaint()
                print(
                    tr(self.current_language, "msg_layer_loaded").format(
                        layer_name=lyrName
                    )
                )

            else:
                print(
                    tr(self.current_language, "msg_layer_loaded").format(
                        layer_name=lyrName
                    )
                )

