    # [환경설정] shapefile 문자열(path,code) 분리
    def _parse_shapefile_config_value(self, text):
        if text and ',' in text:
            parts = text.split(',', 1)
            file_path = parts[0].strip().replace("\\", "/")
            obs_code = parts[1].strip() if len(parts) > 1 else ''
            return file_path, obs_code
        return '', ''

    # [환경설정] shapefile 기본값 반환
    def _get_default_shapefile_map(self):
        plugin_path = os.path.dirname(__file__)
        return {
            'waterlevel': f"{plugin_path}/shp/Korea_Waterlevel_EPSG5186.shp,obs_code",
            'rainfall': f"{plugin_path}/shp/Korea_Rainfall_EPSG5186.shp,obs_code",
            'discharge': f"{plugin_path}/shp/Korea_Discharge_EPSG5186.shp,obs_code",
            'daminlet': f"{plugin_path}/shp/Korea_point_IF_mywater_EPSG5186.shp,obs_code",
            'damrelease': f"{plugin_path}/shp/Korea_point_OF_mywater_EPSG5186.shp,obs_code",
            'tidelevel': f"{plugin_path}/shp/Korea_point_Tide_level_EPSG5186.shp,obs_code",
            'watershed': f"{plugin_path}/shp/Korea_watershed_EPSG5186.shp,Name",
            'rivernetwork': f"{plugin_path}/shp/Korea_River_network_EPSG5186.shp,",
        }

    # [환경설정] shapefile 속성값을 인스턴스에 반영
    def _apply_shapefile_values(self, shapefile_map):
        self.shp_waterlevel, self.id_waterlevel = self._parse_shapefile_config_value(shapefile_map.get('waterlevel', ','))
        self.shp_rainfall, self.id_rainfall = self._parse_shapefile_config_value(shapefile_map.get('rainfall', ','))
        self.shp_discharge, self.id_discharge = self._parse_shapefile_config_value(shapefile_map.get('discharge', ','))
        self.shp_daminlet, self.id_daminlet = self._parse_shapefile_config_value(shapefile_map.get('daminlet', ','))
        self.shp_damrelease, self.id_damrelease = self._parse_shapefile_config_value(shapefile_map.get('damrelease', ','))
        self.shp_tidelevel, self.id_tidelevel = self._parse_shapefile_config_value(shapefile_map.get('tidelevel', ','))
        self.shp_watershed, self.id_watershed = self._parse_shapefile_config_value(shapefile_map.get('watershed', ','))        
        self.shp_rivernetwork, self.id_rivernetwork = self._parse_shapefile_config_value(shapefile_map.get('rivernetwork', ','))

    # [환경설정] GIS 레이어 로드/텍스트박스 반영
    def _load_shapefile_layers_and_controls(self):
        pluginPath = os.path.dirname(__file__)

        layer_specs = [
            (self.shp_watershed,  "watershed",   "ogr", 'transparent', self.id_watershed, ''),
            (self.shp_rivernetwork, "rivernetwork", "ogr", '#276bff', self.id_rivernetwork, ''),
            (self.shp_discharge,  "discharge",   "ogr", 'yellow',     self.id_discharge, 'star'),
            (self.shp_daminlet,   "daminlet",    "ogr", 'green',      self.id_daminlet, 'square'),
            (self.shp_damrelease, "damrelease",  "ogr", 'blue',       self.id_damrelease, 'square'),
            (self.shp_rainfall,   "rainfall",    "ogr", 'orange',     self.id_rainfall, 'circle'),
            (self.shp_tidelevel,  "tidelevel",   "ogr", 'purple',     self.id_tidelevel, 'diamond'),
            (self.shp_waterlevel, "waterlevel",  "ogr", 'red',        self.id_waterlevel, 'triangle'),
        ]

        for lyr, lyrName, provider, color, labelText, shape in layer_specs:
            self.add_mapLayer(lyr, lyrName, provider, color, labelText, shape)

        control_specs = [
            (self.shp_watershed,  self.id_watershed,  self.txtBox_env_lyr_watershed,  self.txtBox_env_obscode_watershed),            
            (self.shp_rivernetwork,  self.id_rivernetwork,  self.txtBox_env_lyr_rivernetwork,  self.txtBox_env_obscode_rivernetwork),
            (self.shp_discharge,  self.id_discharge,  self.txtBox_env_lyr_discharge,  self.txtBox_env_obscode_discharge),
            (self.shp_daminlet,   self.id_daminlet,   self.txtBox_env_lyr_daminlet,   self.txtBox_env_obscode_daminlet),
            (self.shp_damrelease, self.id_damrelease, self.txtBox_env_lyr_damrelease, self.txtBox_env_obscode_damrelease),
            (self.shp_rainfall,   self.id_rainfall,   self.txtBox_env_lyr_rainfall,   self.txtBox_env_obscode_rainfall),
            (self.shp_tidelevel,  self.id_tidelevel,  self.txtBox_env_lyr_tidelevel,  self.txtBox_env_obscode_tidelevel),
            (self.shp_waterlevel, self.id_waterlevel, self.txtBox_env_lyr_waterlevel, self.txtBox_env_obscode_waterlevel),
        ]

        for shp_path, obs_code, txt_path, txt_code in control_specs:
            if shp_path and os.path.exists(shp_path):
                txt_path.setText(shp_path)
                txt_code.setText(obs_code)

    # init : PythonConsole 불러오기
    def load_pyConsole(self):
        pythonConsole = iface.mainWindow().findChild(QDockWidget, 'PythonConsole')
        if not pythonConsole or not pythonConsole.isVisible():
            iface.actionShowPythonDialog().trigger()
    
