    # [환경설정] 기본 LSTM 모델 환경설정 추가
    def _ensure_default_lstm_model_env(self):
        default_model_path = os.path.normpath(
            os.path.join(self.program_path, 'ai_algorithm', 'lstm')
        )

        # lstm, Lstm 등 대소문자가 다른 기존 항목도 확인
        existing_name = next(
            (
                model_name
                for model_name in self.model_env_info.keys()
                if str(model_name).strip().lower() == 'lstm'
            ),
            None
        )

        # 기존 LSTM 설정이 없는 경우 기본값 생성
        if existing_name is None:
            self.model_env_info['LSTM'] = {
                'python_path': '',
                'model_path': default_model_path
            }
            return

        # 기존 lstm 항목의 이름을 LSTM으로 통일
        if existing_name != 'LSTM':
            self.model_env_info['LSTM'] = self.model_env_info.pop(existing_name)

        lstm_info = self.model_env_info['LSTM']

        if not isinstance(lstm_info, dict):
            lstm_info = {}
            self.model_env_info['LSTM'] = lstm_info

        # Python 경로는 기존 설정값을 유지하고, 없으면 빈 문자열
        lstm_info['python_path'] = str(
            lstm_info.get('python_path', '') or ''
        ).strip()

        # 모델 경로가 비어 있을 때만 기본 LSTM 폴더 지정
        if not str(lstm_info.get('model_path', '') or '').strip():
            lstm_info['model_path'] = default_model_path

    # [환경설정] DB Tabelspace Name 목록 가져오기
    def get_tablespace_name(self):

        conn = mariadb.connect(**self.db_config_admin)
        cur = conn.cursor()

        target_tables = ['waterlevel', 'rainfall', 'discharge', 'daminlet', 'damrelease', 'tidelevel', 'watershed']
            
        query = f"""
            SELECT TABLE_SCHEMA
            FROM information_schema.TABLES
            WHERE TABLE_NAME IN ({','.join(['?' for _ in target_tables])})
            AND TABLE_SCHEMA NOT IN ('mysql', 'information_schema', 'performance_schema', 'sys')
            GROUP BY TABLE_SCHEMA
            HAVING COUNT(DISTINCT TABLE_NAME) = {len(target_tables)};
        """

        cur.execute(query, target_tables)
        tablespaces = [row[0] for row in cur]
        cur.close()
        conn.close()

        if not tablespaces:
            print(
                tr(
                    self.current_language,
                    "msg_no_available_tablespace"
                )
            )         
            return
        else:
            self.combo_tblspace.reset_items(tablespaces)
            self.combo_tblspace.set_selected_text(self.db_tablespace)
    
