    # [환경설정] model_env 설정 저장
    def _save_model_env_config(self):
        if not self.config.has_section('model_env'):
            self.config.add_section('model_env')

        model_env_save = {}
        for model_name, info in (self.model_env_info or {}).items():
            model_key = str(model_name).strip()
            if model_key == '':
                continue

            if not isinstance(info, dict):
                info = {}

            model_env_save[model_key] = {
                'python_path': str(info.get('python_path', '') or '').strip(),
                'model_path': str(info.get('model_path', '') or '').strip()
            }

        self.config.set(
            'model_env',
            'items_json',
            json.dumps(model_env_save, ensure_ascii=False)
        )

