    def Dashboard_addModelName(self):
        addModelText = self.txtBox_dash_modelName.text().strip()
        if addModelText is not '':
            self.listWidget_dash_modelName.addItem(addModelText)
            self.txtBox_dash_modelName.setText('')

    # tab [대시보드] : Level5 삭제
    def Dashboard_deleteModelName(self):
        self.removeItemRow = self.listWidget_dash_modelName.currentRow()
        if (self.removeItemRow>=0):
            self.listWidget_dash_modelName.takeItem(self.removeItemRow)       
            self.txtBox_dash_modelName.setText('')
            self.listWidget_dash_modelName.setCurrentRow(-1)

    # tab [대시보드] : Level5 선택
    def Dashboard_ClickedListModelName(self):     
        self.txtBox_dash_modelName.setText('')
        ItemRow = self.listWidget_dash_modelName.currentRow()
        if (ItemRow>=0):
            self.txtBox_dash_modelName.setText(self.listWidget_dash_modelName.currentItem().text())
    
    # tab [대시보드] : Level5 수정
    def Dashboard_modifyModelName(self):     
        mod_text = self.txtBox_dash_modelName.text().strip()
        if (mod_text == '') : return

        ItemRow = self.listWidget_dash_modelName.currentRow()
        if (ItemRow>=0):
            self.listWidget_dash_modelName.takeItem(ItemRow)
            self.listWidget_dash_modelName.insertItem(ItemRow, mod_text)       
            self.txtBox_dash_modelName.setText('')
            self.listWidget_dash_modelName.setCurrentRow(-1)

    #################################################################################

    # tab [데이터 관리] : [데이터파일 Import] 파일불러오기(...) Button Event
    def LoadDataFile(self):

        fileDatas, _ = QFileDialog.getOpenFileNames(self, tr(self.current_language, "filedlg_open_file"), '', 'csv file(*.csv)')
        
        # 선택된 파일이 없을 경우, 취소
        if len(fileDatas) == 0: return

        # set_tableWidget
        labels = ['File Name', 'File Path']
        self.tbl_showData.clearContents()
        nb_row = len(fileDatas)
        nb_col = len(labels)
        self.tbl_showData.setRowCount(nb_row)
        self.tbl_showData.setColumnCount(nb_col)
        self.tbl_showData.setHorizontalHeaderLabels(labels)
  
        fileNames = []
        for row in range(nb_row):
            dir, fileName = os.path.split(fileDatas[row])
            fileNames.append(fileName)
            item = QTableWidgetItem(fileName)
            item.setTextAlignment(Qt.AlignHCenter | Qt.AlignVCenter)
            self.tbl_showData.setItem(row, 0, item)
            item = QTableWidgetItem(dir)
            item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
            self.tbl_showData.setItem(row, 1, item)

        self.txtBox_data_loadDataFile.setText(str(fileNames))
        self.tbl_showData.resizeColumnsToContents()
    
    # tab [데이터 관리] : [데이터파일 Import] 저장하기 (DB 또는 FILE)
    def FileCSV_Save(self):

        # 1. 입력테이블명
        strTableNm = self.cb_dataTable.currentData()

        # 테이블을 선택하지 않은 경우
        if not strTableNm:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_data_file_db_import"),
                tr(self.current_language, "msg_save_table_query"),
                QMessageBox.Ok
            )
            return

        # 저장분류
        bSaveFile = self.ckb_data_saveFile.isChecked()          #파일저장
        bSaveDbImport = self.ckb_data_saveDbImport.isChecked()  #DB_IMPORT

        if not bSaveFile and not bSaveDbImport:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_data_file_db_import"),
                tr(self.current_language, "msg_select_save_destination")
            )
            return

        # 2. 입력된 파일이 있는지 확인한다. (없으면취소, 있으면데이터재확인)
        if (self.tbl_showData.rowCount() == 0):
            QMessageBox.warning(self, tr(self.current_language, "title_data_file_db_import"), tr(self.current_language, "msg_there_no_data_import"), QMessageBox.Ok)
            return
        else:
            strDataName = ""
            if (strTableNm == "waterlevel"):
                strDataName = "WaterLevel"
            elif (strTableNm == "discharge"):
                strDataName = "Discharge"
            elif (strTableNm == "rainfall"):
                strDataName = "Rainfall"
            elif (strTableNm == "daminlet"):
                strDataName = "DamInflow"
            elif (strTableNm == "damrelease"):
                strDataName = "DamOutflow"
            elif (strTableNm == "tidelevel"):
                strDataName = "TideLevel"
            elif (strTableNm == "watershed"):
                strDataName = "Watershed"
            elif (strTableNm == "predict_rain"):
                strDataName = "predict_rain"
            else:
                strDataName = "None"

            msgImport = tr(
                self.current_language,
                "msg_confirm_import_file"
            ).format(table_name=strDataName)
            btnImportOK = QMessageBox.warning(self, tr(self.current_language, "title_data_file_db_import"), msgImport,
                                              QMessageBox.Yes | QMessageBox.Cancel)
            if btnImportOK == QMessageBox.Cancel:
                QMessageBox.warning(self, tr(self.current_language, "title_data_file_db_import"), tr(self.current_language, "msg_operation_been_canceled"), QMessageBox.Ok)
                return       

        # 3. 중복데이터가 데이터베이스에 존재할 경우, 업데이트 여부를 선택한다.
        #    Yes-파일자료(또는품질관리자료)로 DB 데이터 수정, No-DB에 있는 데이터 그대로 사용, 취소-Import작업취소
        isUpdate = True
        buttonReply = QMessageBox.warning(self, tr(self.current_language, "title_data_file_db_import"), tr(self.current_language, "msg_if_duplicate_data_exists_want_update"),
                                          QMessageBox.Yes | QMessageBox.No  | QMessageBox.Cancel)
        if buttonReply == QMessageBox.No:
            isUpdate = False
        elif buttonReply == QMessageBox.Yes:
            isUpdate = True
        else:
            return

        # 4. 품질관리여부
        bRemoveOutlier = self.ckb_data_option1.isChecked()      #이상치제거
        bRemoveMissingVAL = self.ckb_data_option2.isChecked()   #결측치보정    
        RemoveMissingVAL_time = int(self.sp_data_option2_interpol_time.value())
        
        # 5-1. 파일저장 폴더
        dirPath = ''
        if bSaveFile:
            dirPath = QFileDialog.getExistingDirectory(self)
            if not os.path.exists(dirPath):
                QMessageBox.warning(self, tr(self.current_language, "title_data_file_db_import"), tr(self.current_language, "msg_no_folder_selected"))
                return
            
        # 6. 프로세스 실행        
        # 실행 중 버튼 비활성화
        self.btn_dataSave.setEnabled(False)

        # 파일 리스트
        file_list = [
            {'path': os.path.join(self.tbl_showData.item(row, 1).text(),
                                self.tbl_showData.item(row, 0).text())}
            for row in range(self.tbl_showData.rowCount())
        ]

        # 옵션 전달
        options = {
            'table_nm' : strTableNm,
            'is_update': isUpdate,
            'remove_outlier': self.ckb_data_option1.isChecked(),
            'fill_missing': self.ckb_data_option2.isChecked(),    
            'fill_missing_time': int(self.sp_data_option2_interpol_time.value()),
            'save_db': self.ckb_data_saveDbImport.isChecked(),
            'save_file': self.ckb_data_saveFile.isChecked(),
            'save_dir': dirPath,
            'db_config' : self.db_config,
            'tablespace' : self.db_tablespace
        }

        self.progressBar_file.setValue(0)
        self.progressBar_allfile.setValue(0)
        self.progressBar_file.show()
        self.progressBar_allfile.show()        
        self.lbl_status.show()
        
        self.data_importer = DataImporter(file_list, options, lang=self.current_language)
        self.data_importer.allProgressChanged.connect(self.progressBar_allfile.setValue)
        self.data_importer.fileProgressChanged.connect(self.progressBar_file.setValue)
        self.data_importer.fileChanged.connect(lambda fn: self.lbl_status.setText(f"{fn}"))
        self.data_importer.statusMessage.connect(lambda msg: print(msg))
        self.data_importer.errorOccured.connect(lambda e: QMessageBox.critical(self, tr(self.current_language, "title_data_file_db_import"), e))
        self.data_importer.finishedSignal.connect(self.on_finished)
        self.data_importer.start() 

    # tab [데이터 관리] : [데이터파일 Import] 저장하기 - 중간에 종료시 이벤트
    def stop_worker(self):
        if self.data_importer:
            self.data_importer.stop()
            self.lbl_status.setText(tr(self.current_language, "status_stop_requested"))      

    # tab [데이터 관리] : [데이터파일 Import] 저장하기 - 작업종료 후 이벤트
    def on_finished(self):
        
        QMessageBox.information(self, tr(self.current_language, "title_data_file_db_import"), tr(self.current_language, "msg_all_files_been_saved"))

        # 처리 완료 후 progressBar_file, lbl_status 숨김        
        self.progressBar_file.hide()
        self.lbl_status.hide()        
        self.progressBar_file.setValue(0)
        self.progressBar_allfile.setValue(0)
        self.lbl_status.clear()
        self.data_importer = None

        # 처리 완료 후, 테이블스페이스정보 & 데이터셋 기간정보 재설정
        self.get_selected_tablespace(self.db_tablespace)

        # 버튼 다시 활성화
        self.btn_dataSave.setEnabled(True)     

    # tab [데이터 관리] : 데이터Import의 체크박스/보간시간 활성화 상태를 관리
    def update_data_interpolation_time_enabled(self):
        missing_enabled = self.ckb_data_option2.isEnabled()
        outlier_enabled = self.ckb_data_option1.isEnabled()

        interpolation_enabled = (
            (missing_enabled and self.ckb_data_option2.isChecked())
            or
            (outlier_enabled and self.ckb_data_option1.isChecked())
        )

        self.sp_data_option2_interpol_time.setEnabled(
            interpolation_enabled
        )

    # tab [데이터 관리] : [데이터파일 Import] 테이블선택 Combobox Event
    def SetDataTableType(self, index):
        
         # 선택한 자료 종류
        strTableNm = self.cb_dataTable.currentData()

        if self.is_select_text(strTableNm):
            return

        # 결측치 보정 적용 자료
        missing_value_tables = {
            "waterlevel",   # 수위
            "rainfall",     # 강우
            "discharge",    # 유량
            "daminlet",     # 댐 유입량
            "damrelease",   # 댐 방류량
            "tidelevel"     # 조위
        }

        # 이상치 보정 적용 자료
        outlier_tables = {
            "waterlevel",   # 수위
            "discharge",    # 유량
            "daminlet",     # 댐 유입량
            "damrelease",   # 댐 방류량
            "tidelevel"     # 조위
        }

        # 결측치 보정 사용 여부
        missing_enabled = strTableNm in missing_value_tables

        # 이상치 보정 사용 여부
        outlier_enabled = strTableNm in outlier_tables

        self.ckb_data_option2.setEnabled(missing_enabled)
        self.ckb_data_option1.setEnabled(outlier_enabled)

        # 결측치 보정과 이상치 보정 모두 보간시간을 사용한다.
        # 사용할 수 없는 옵션은 체크 해제
        if not missing_enabled:
            self.ckb_data_option2.setChecked(False)

        if not outlier_enabled:
            self.ckb_data_option1.setChecked(False)

        # CSV 파일 저장 및 DB 저장 기능
        self.ckb_data_saveDbImport.setEnabled(True)
        self.ckb_data_saveFile.setEnabled(True)

        self.update_data_interpolation_time_enabled()

    # tab [데이터 관리] : [openAPI 불러오기] 조회 Button Event
    def Search_OpenAPIData(self):

        # 조회전, 입력값 체크
        if (self.CheckOpenAPI_SearchDataInputValue() == False):
            return

        self.tbl_apiData.clearContents()

        # 인터넷연결확인
        ipaddress = socket.gethostbyname(socket.gethostname())
        if ipaddress == "127.0.0.1":
            QMessageBox.warning(self, tr(self.current_language, "title_query_openapi"), tr(self.current_language, "msg_invalid_internet_connection"), QMessageBox.Ok)
            return        

        # 선택된 실제 자료 유형 가져오기
        obs_type = self.cb_apiObsType.currentData()

        # 자료 유형을 선택하지 않은 경우
        if not obs_type:
            return

        # 자료 유형별 OpenAPI 요청 종류와 응답 컬럼 설정
        api_type_map = {
            "waterlevel": ("waterlevel", "wl"),
            "discharge":  ("waterlevel", "fw"),
            "rainfall":   ("rainfall", "rf"),
            "daminlet":   ("dam", "inf"),
            "damrelease": ("dam", "tototf"),
            #"tidelevel":  ("tidelevel", "tide_level")
            "tidelevel":  ("tidelevel", "bscTdlvHgt")
        }

        api_info = api_type_map.get(obs_type)

        # 지원하지 않는 자료 유형인 경우
        if api_info is None:
            return

        strDataType, colName = api_info

        # 관측소번호 설정
        strObsId = self.selected_api_obsId 

        # 조회기간 설정
        start = self.dt_apiStartDt.text()
        end = self.dt_apiEndDt.text()
        startDate = "{0}{1}{2}0000".format(start[0:4], start[5:7], start[8:10])
        endDate = "{0}{1}{2}2350".format(end[0:4], end[5:7], end[8:10])

        # openAPI 정보 설정

        # 환경부 한강홍수통제소 자료 (10분단위, 최대1개월까지 조회가능)
        # 낙동강, 금강, 영산강 권역의 자료는 한강 권역의 자료 보다 늦게 수집 됩니다.
        # 한강 권역 : 7~8분, 낙동강, 금강, 영산강 권역 : 11분 이상, 따라서 관측소별로 최종자료 시간이 다를 수 있습니다.
        # 수위/유량 데이터 url (wlobscd, ymdhm, wl, fw) - 관측소code, 년월일시분(yyyyMMddHHmm), 수위자료(m)(#), 유량자료(m3/s)(#)
        # url_waterlevel = 'https://api.hrfco.go.kr/52832662-D130-4239-9C5F-730AD3BE6BC6/waterlevel/list/10M/1001607/202108010000/202108012350.json'
        # 강우 url (rfobscd, ymdhm, rf) - 관측소code, 년월일시분(yyyyMMddHHmm), 강수량자료(mm)(#)
        # url_rainfall = 'https://api.hrfco.go.kr/52832662-D130-4239-9C5F-730AD3BE6BC6/rainfall/list/10M/10014010/202208090000/202208092350.json'
        # 댐유입/방류 데이터 url (dmobscd, ymdhm, swl, inf, sfw, ecpc, tototf) - 코드, 일시분, 현재수위, 유입량(#), 저수량, 공용량, 총방류량(#)
        # url_dam = 'https://api.hrfco.go.kr/52832662-D130-4239-9C5F-730AD3BE6BC6/dam/list/10M/1001210/202308090000/202308101700.json'
        # 해양수산부 국립해양조사원 조위관측소 자료 (1분단위, 최대1일까지 조회가능) <- 조회url변경됨

        url = ""        # openAPI service_url
        myKey = ""      # openAPI KEY (KEY정보 변경하기)
        url_data = ''
        if obs_type == "tidelevel":
            url = "https://apis.data.go.kr/1192136/surveyTideLevel/GetSurveyTideLevelApiService?serviceKey={0}&type=json&obsCode={1}&reqDate={2}&min=10&numOfRows=144&include=obsrvnDt%2C%20bscTdlvHgt"
            myKey = "wmAG/iy3jD2vp5PMB7i4e4T7ibpA4Pce3xUfKFROtMOKL3Z51DVYIvKTsPxgcSdfVWwPRE1TyMjzzkLG3XvDTQ=="
            url_data = url.format(myKey, strObsId, startDate[0:8])
        else:
            url = "https://api.hrfco.go.kr/{0}/{1}/list/10M/{2}/{3}/{4}.json"
            myKey = "52832662-D130-4239-9C5F-730AD3BE6BC6"
            url_data = url.format(myKey, strDataType, strObsId, startDate, endDate)

        # openAPI 자료 가져오기
        response = requests.get(url_data, verify=False)
        if response.status_code == 200:
            data = json.loads(response.text)
            if obs_type == "tidelevel":                  

                # 공공데이터포털 조위 API 응답 구조 : data['body']['items']['item']
                header = data.get("header", {})
                # API 처리 결과 확인
                if str(header.get("resultCode", "")) != "00":
                    self.tbl_apiData.setRowCount(0)
                    self.tbl_apiData.setColumnCount(0)

                    QMessageBox.warning(
                        self,
                        tr(self.current_language, "title_query_openapi"),
                        "[{0}] {1}".format(
                            header.get("resultCode", ""),
                            header.get("resultMsg", "")
                        ),
                        QMessageBox.Ok
                    )
                    return False

                # 조위자료 목록 가져오기
                tide_items = data.get("body", {}).get("items", {}).get("item", [])

                # 조회결과가 한 건이면 dict 형태일 수 있으므로 list로 변환한다.
                if isinstance(tide_items, dict):
                    tide_items = [tide_items]

                if not isinstance(tide_items, list):
                    tide_items = []

                # 조위자료가 없는 경우
                if len(tide_items) == 0:

                    self.tbl_apiData.setRowCount(0)
                    self.tbl_apiData.setColumnCount(0)

                    QMessageBox.information(
                        self,
                        tr(self.current_language, "title_query_openapi"),
                        "조회된 조위자료가 없습니다.",
                        QMessageBox.Ok
                    )
                    return False

                # 표에 표시할 10분 단위 자료 생성
                result_rows = []

                for tide_item in tide_items:

                    # 관측일시: obsrvnDt
                    # 조위값: bscTdlvHgt
                    date_text = str(
                        tide_item.get("obsrvnDt", "")
                    ).strip()

                    tide_value = tide_item.get("bscTdlvHgt", None)

                    if date_text == "" or tide_value is None:
                        continue

                    datetime_text = pd.to_datetime(
                        date_text,
                        errors="coerce"
                    )

                    if pd.isna(datetime_text):
                        continue

                    result_rows.append(
                        (
                            datetime_text.strftime("%Y-%m-%d %H:%M"),
                            tide_value
                        )
                    )

                # 날짜순으로 정렬한다.
                result_rows.sort(key=lambda x: x[0])

                # OpenAPI 조회결과 표에 표시한다.
                labels = ["Date", "Data"]

                self.tbl_apiData.setRowCount(len(result_rows))
                self.tbl_apiData.setColumnCount(len(labels))
                self.tbl_apiData.setHorizontalHeaderLabels(labels)

                for row, (date_text, tide_value) in enumerate(result_rows):

                    item = QTableWidgetItem(str(date_text))
                    item.setTextAlignment(Qt.AlignHCenter | Qt.AlignVCenter)
                    self.tbl_apiData.setItem(row, 0, item)

                    item = QTableWidgetItem(str(tide_value))
                    item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                    self.tbl_apiData.setItem(row, 1, item)

                self.tbl_apiData.resizeColumnsToContents()

            else:
                for errData in data.keys():
                    if errData == "message":
                        self.tbl_apiData.setRowCount(0)
                        self.tbl_apiData.setColumnCount(0)
                        QMessageBox.warning(self, tr(self.current_language, "title_query_openapi"), data[errData], QMessageBox.Ok)
                        return False

                df = pd.json_normalize(data['content'])                                
                df['ymdhm'] = pd.to_datetime(df['ymdhm'], errors='coerce')
                df['ymdhm'] = df['ymdhm'].dt.strftime("%Y-%m-%d %H:%M")
                labels = ['Date', 'Data']
                nb_row = len(df)
                nb_col = len(labels)
                self.tbl_apiData.setRowCount(nb_row)
                self.tbl_apiData.setColumnCount(nb_col)
                self.tbl_apiData.setHorizontalHeaderLabels(labels)
                for row in range(len(df)):
                    item = QTableWidgetItem(str(df.loc[nb_row - row - 1]['ymdhm']))
                    item.setTextAlignment(Qt.AlignHCenter | Qt.AlignVCenter)
                    self.tbl_apiData.setItem(row, 0, item)
                    item = QTableWidgetItem(str(df.loc[nb_row - row - 1][colName]))
                    item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                    self.tbl_apiData.setItem(row, 1, item)

                self.tbl_apiData.resizeColumnsToContents()

            return True
        else:
            errMsg = str(response.status_code)
            QMessageBox.warning(self, tr(self.current_language, "title_query_openapi"), errMsg, QMessageBox.Ok)
            return False

    # tab [데이터 관리] : [openAPI 불러오기] 조회전, 입력값 체크
    def CheckOpenAPI_SearchDataInputValue(self):        

        # 0. 자료 종류를 선택했는지 확인
        obs_type = self.cb_apiObsType.currentData()

        if not obs_type:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                tr(self.current_language, "msg_select_type_data_query"),
                QMessageBox.Ok
            )
            return False

        # 1. 관측소번호를 입력했는지 확인
        strObsId = self.selected_api_obsId

        if strObsId is None:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                tr(
                    self.current_language,
                    "msg_enter_observation_station_number_query"
                ),
                QMessageBox.Ok
            )
            return False

        # 2. 조회기간이 올바른지 확인
        start_date = self.dt_apiStartDt.date()
        end_date = self.dt_apiEndDt.date()

        if start_date > end_date:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                tr(
                    self.current_language,
                    "msg_start_date_cannot_later_than_end_date"
                ),
                QMessageBox.Ok
            )
            return False

        # 3. 조회기간 제한 확인
        # 조위는 1일, 그 외 자료는 1개월 이내로 조회
        start = datetime(
            start_date.year(),
            start_date.month(),
            start_date.day()
        )

        end = datetime(
            end_date.year(),
            end_date.month(),
            end_date.day()
        )

        one_month_later = start + relativedelta(months=1)

        # 조위 자료는 시작일과 종료일이 같아야 함
        if obs_type == "tidelevel":
            if start_date != end_date:
                QMessageBox.warning(
                    self,
                    tr(self.current_language, "title_query_openapi"),
                    tr(
                        self.current_language,
                        "msg_query_period_limited_one_day"
                    ),
                    QMessageBox.Ok
                )
                return False

        # 조위 이외의 자료는 시작일로부터 1개월 이내로 제한
        else:
            if end.date() > one_month_later.date():
                QMessageBox.warning(
                    self,
                    tr(self.current_language, "title_query_openapi"),
                    tr(
                        self.current_language,
                        "msg_query_period_limited_one_month"
                    ),
                    QMessageBox.Ok
                )
                return False

        return True

    # tab [데이터 관리] : [openAPI 불러오기] 관측소목록 변경
    def SetOpenAPI_ObsType(self, index):        

        # 수위/유량 관측소 제원정보
        # https://api.hrfco.go.kr/{인증키}/waterlevel/info.json
        # 강우 관측소 제원정보
        # https://api.hrfco.go.kr/{인증키}/rainfall/info.json
        # 댐 제원정보
        # https://api.hrfco.go.kr/{인증키}/dam/info.json
        # 조위 관측소 제원정보 (변경)

        # 기존 선택 관측소 초기화
        self.selected_api_obsId = None
        self.combo_api_obsId.reset_items([])

        # 선택된 실제 자료 유형 가져오기
        obs_type = self.cb_apiObsType.currentData()

        # 자료 유형을 선택하지 않은 경우
        if not obs_type:
            return False

        # 인터넷 연결 확인
        try:
            ipaddress = socket.gethostbyname(socket.gethostname())
        except socket.gaierror:
            return False

        if ipaddress == "127.0.0.1":
            return False

        # 관측소 종류에 따라 API 주소와 관측소코드 컬럼 설정
        hrfco_url = "https://api.hrfco.go.kr/{0}/{1}/info.json"
        hrfco_key = "52832662-D130-4239-9C5F-730AD3BE6BC6"

        # 실제 자료 유형: (API 자료 유형, 관측소코드 컬럼명)
        api_info_map = {
            "waterlevel": ("waterlevel", "wlobscd"),
            "discharge":  ("waterlevel", "wlobscd"),
            "rainfall":   ("rainfall", "rfobscd"),
            "daminlet":   ("dam", "dmobscd"),
            "damrelease": ("dam", "dmobscd")
        }

        # 조위 자료
        if obs_type == "tidelevel":
            khoa_url = (
                "https://khoa.go.kr/oceandata/api/obsServiceObj/search.do?ServiceKey={0}&ResultType=json"
            )
            khoa_key = "d1UW5O5YQ4gJkim1X3lAaw=="
            colName = "obs_post_id"
            url_obs = khoa_url.format(khoa_key)

        # 수위, 유량, 강우, 댐 유입량, 댐 방류량
        else:
            api_info = api_info_map.get(obs_type)

            # OpenAPI에서 지원하지 않는 자료 유형인 경우
            if api_info is None:
                return False

            strDataType, colName = api_info
            url_obs = hrfco_url.format(hrfco_key, strDataType)

        # OpenAPI 관측소 제원정보 가져오기
        try:
            response = requests.get(
                url_obs,
                verify=False,
                timeout=30
            )
        except requests.RequestException as e:
            self.combo_api_obsId.reset_items([])

            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                str(e),
                QMessageBox.Ok
            )
            return False

        # HTTP 요청 실패
        if response.status_code != 200:
            self.combo_api_obsId.reset_items([])

            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                str(response.status_code),
                QMessageBox.Ok
            )
            return False

        # JSON 응답 변환
        try:
            data = response.json()
            items = []

            # 조위 관측소 응답 처리
            if obs_type == "tidelevel":
                obs_data = data.get("result", {}).get("data", [])

            # 수위, 유량, 강우, 댐 관측소 응답 처리
            else:
                obs_data = data.get("content", [])

            # 관측소코드 목록 생성
            for obs_info in obs_data:
                if not isinstance(obs_info, dict):
                    continue

                codeNo = obs_info.get(colName)

                if codeNo is None:
                    continue

                codeNo = str(codeNo).strip()

                # 조위는 DT_로 시작하는 관측소만 목록에 표시한다.
                if obs_type == "tidelevel":
                    if not codeNo.upper().startswith("DT_"):
                        continue

                items.append(codeNo)

            # 중복 제거 후 정렬하여 관측소 목록에 표시한다.
            items = sorted(set(items))

            self.combo_api_obsId.reset_items(items)
            return True

        except (ValueError, TypeError, AttributeError, KeyError) as e:
            self.combo_api_obsId.reset_items([])

            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                str(e),
                QMessageBox.Ok
            )
            return False

    # tab [데이터 관리] : [openAPI 불러오기] 파일저장
    def Save_OpenAPIData(self):        

        # 저장할 내용이 없는 경우 취소
        if self.tbl_apiData.rowCount() == 0:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_openapi"),
                tr(self.current_language, "msg_there_no_data_save"),
                QMessageBox.Ok
            )
            return

        # 선택된 실제 자료 유형 가져오기
        obs_type = self.cb_apiObsType.currentData()

        # 자료 유형을 선택하지 않은 경우
        if not obs_type:
            return

        # 선택된 관측소번호
        strObsId = self.selected_api_obsId

        # 조위 자료일 경우 날짜 형식을 변경하여 저장
        bChangeDateType = (obs_type == "tidelevel")

        # 저장 파일 경로 선택
        file = QFileDialog.getSaveFileName(
            self,
            tr(self.current_language, "filedlg_save_file"),
            str(strObsId or ""),
            "*.csv"
        )

        # 저장 경로를 선택하지 않은 경우
        if not file[0]:
            return

        # 저장 경로 설정
        saveFilePath = file[0]

        # 파일저장
        saveFile = open(saveFilePath, 'w', newline='')
        wr = csv.writer(saveFile)
        for row in range(self.tbl_apiData.rowCount()):
            rowdata = []
            for col in range(self.tbl_apiData.columnCount()):
                itemText = str(self.tbl_apiData.item(row, col).text())
                if ((col == 0) and (bChangeDateType == True)):
                    itemText = "{0}{1}{2}{3}{4}".format(itemText[0:4],itemText[5:7],itemText[8:10], itemText[11:13],itemText[14:16])
                rowdata.append(itemText)
            wr.writerow(rowdata)
        saveFile.close()

        QMessageBox.information(self, tr(self.current_language, "title_query_openapi"), tr(self.current_language, "msg_data_been_saved_successfully"), QMessageBox.Ok)

    # tab [데이터 관리] : [데이터조회] 관측소종류에 따른 목록변경
    def SetDataSearchTableData(self, index):
        self.SearchTableObsIdList()

    # tab [데이터 관리] : [데이터조회] 관측소목록 Combobox 설정
    def SearchTableObsIdList(self):        

        conn = None

        try:
            self.selected_obsId = None

            # 데이터조회
            conn = mariadb.connect(**self.db_config)
            cur = conn.cursor()

            # 데이터관리 - 선택된 실제 DB 테이블명 가져오기
            strTblNm = self.cb_searchTable.currentData()

            # 테이블을 선택하지 않은 경우
            if not strTblNm:
                # 관측소번호 콤보박스 초기화
                items = [self.select_text()]
                self.combo_obs_dblist.reset_items(items)
                return

            # 관측소코드 목록 조회
            select_query = "SELECT OBS_ID FROM {0} GROUP BY OBS_ID".format(strTblNm)
            cur.execute(select_query)
            resultset = cur.fetchall()

            # 관측소번호 콤보박스 갱신
            items = []
            for idx in range(len(resultset)):
                items.append(resultset[idx][0])

            self.combo_obs_dblist.reset_items(items)

        except mariadb.Error as e:
            print(
                tr(self.current_language, "msg_query_database_error").format(
                    error=e
                )
            )

        except Exception as e:
            print(
                tr(self.current_language, "msg_query_database_exception").format(
                    error=e
                )
            )

        finally:
            if conn:
                conn.close()

    # tab [데이터 관리] : [데이터조회] 조회전, 입력값 체크
    def CheckSearchDataInputValue(self):
        
         # 1. 관측소 종류를 입력했는지 확인
        strTbl = self.cb_searchTable.currentData()

        if not strTbl:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_query_database"),
                tr(self.current_language, "msg_select_table_query"),
                QMessageBox.Ok
            )
            return False

        # 2.관측소번호를 입력했는지,
        strObsId = self.selected_obsId 
        if (strObsId == None):
            QMessageBox.warning(self, tr(self.current_language, "title_query_database"), tr(self.current_language, "msg_enter_observation_station_id_query"), QMessageBox.Ok)
            return False

        # 3. 조회기간이 올바른지(시작일이 종료일보다 크거나 같은지)
        if (self.dt_data_startTime.date() > self.dt_data_endTime.date()):
            QMessageBox.warning(self, tr(self.current_language, "title_query_database"), tr(self.current_language, "msg_start_date_cannot_later_than_end_date"), QMessageBox.Ok)
            return False

        return True

    # tab [데이터 관리] : [데이터조회] 조회 Button Event
    def SearchData(self):

        # 조회전, 입력값 체크하기
        if (self.CheckSearchDataInputValue() == False):
            return

        # 관측소종류
        strTblNm = self.cb_searchTable.currentData()

        # 테이블을 선택하지 않은 경우
        if not strTblNm:
            return

        # 관측소코드
        strObsId = self.selected_obsId 

        # 자료종류 (0-표준화자료, 1-결측치보정자료, 2-이상치보정자료) - 모두 표출함

        # 조회기간 설정
        start = self.dt_data_startTime.text()
        end = self.dt_data_endTime.text()
        sql_date = "date_format(DT_DATE, '%Y-%m-%d') between '{0}' and '{1}'".format(start, end)

        # 데이터 조회
        conn = None

        try:
            conn = mariadb.connect(**self.db_config)
            cur = conn.cursor()
            select_all_query = "select OBS_ID, DT_DATE, DT_DATA, MI_DATA, OI_DATA from {} where OBS_ID = '{}' and ({}) ORDER BY DT_DATE".format(strTblNm, strObsId, sql_date)
            cur.execute(select_all_query)
            resultset = cur.fetchall()
        except mariadb.Error as e:
            print("오류 발생: {e}")
        except Exception as e:
            print("[기타 오류] {e}")
        finally:
            if conn:
                conn.close()

        # 그래프 그리기
        if len(resultset) == 0:    

            myfig = go.Figure()
            myfig.update_layout(
                xaxis=dict(title='Time'),
                yaxis=dict(title='Value'),
                margin=dict(l=0, r=60, t=30, b=0)
            )

            # HTML로 임시 저장
            with tempfile.NamedTemporaryFile(delete=False, suffix=".html") as f:
                temp_html_path = f.name
                myfig.write_html(temp_html_path)
            
            self.search_data_fig = myfig

            # QWebEngineView에 로드
            self.web_view.load(QtCore.QUrl.fromLocalFile(temp_html_path))
            
            QMessageBox.warning(self, tr(self.current_language, "title_query_database"), tr(self.current_language, "msg_no_data_found"), QMessageBox.Ok)       


        else:
            x_temp = [i[1] for i in resultset]
            y_temp = [self.convert_data_nullToNan(i[2]) for i in resultset]
            strTitle = "{0}({1}) {2}~{3}".format(strTblNm, strObsId, str(x_temp[0])[0:16], str(x_temp[len(x_temp)-1])[0:16])
  
            y_temp1 = [self.convert_data_nullToNan(i[2]) for i in resultset]                  
            y_temp2 = [self.convert_data_nullToNan(i[3]) for i in resultset]
            y_temp3 = [self.convert_data_nullToNan(i[4]) for i in resultset]

            # x축 데이터, y축 데이터
            layout = go.Layout(
                font=dict(family="Malgun Gothic, sans-serif"),  
                xaxis=dict(
                    title="time",
                    tickformat="%Y-%m-%d %H:%M",    
                ),
                yaxis=dict(title="data"),
                legend=dict(
                    x=1.05,             
                    y=1,                
                    xanchor='left',    
                    yanchor='top',      
                    bgcolor='rgba(255,255,255,0.5)',  
                ),
            )

            myfig = go.Figure(layout=layout)            
            
            myfig.add_trace(go.Scatter(x=x_temp, y=y_temp1, mode="lines", name=tr(self.current_language, "combo_item_normalized_data")))
            myfig.add_trace(go.Scatter(x=x_temp, y=y_temp2, mode="lines", name=tr(self.current_language, "combo_item_missing_value_correction")))
            myfig.add_trace(go.Scatter(x=x_temp, y=y_temp3, mode="lines", name=tr(self.current_language, "combo_item_outlier_filtered_data")))
            
            # 레이아웃 및 인터랙션 설정
            myfig.update_layout(
                xaxis=dict(title='Time', rangeslider_visible=True),
                yaxis=dict(title='Value'),
                margin=dict(l=0, r=60, t=30, b=0),
                legend=dict(x=1.02, y=1, xanchor='left', yanchor='top')
            )


            # HTML로 임시 저장
            with tempfile.NamedTemporaryFile(delete=False, suffix=".html") as f:
                temp_html_path = f.name
                myfig.write_html(temp_html_path)
            
            self.search_data_fig = myfig

            # QWebEngineView에 HTML 로드
            self.web_view.load(QtCore.QUrl.fromLocalFile(temp_html_path))


    # tab [데이터 관리] : JavaScript 문자열에서 문제가 되는 문자 처리
    def escape_javascript_text(self, text):
        return (
            str(text)
            .replace("\\", "\\\\")
            .replace("'", "\\'")
            .replace("\r", "\\r")
            .replace("\n", "\\n")
        )


    # tab [데이터 관리] : [데이터조회] 언어에 따라 범례 Update
    def update_search_data_graph_language(self, lang):
        if self.search_data_fig is None:
            return

        legend_names = [
            tr(lang, "combo_item_normalized_data"),
            tr(lang, "combo_item_missing_value_correction"),
            tr(lang, "combo_item_outlier_filtered_data"),
        ]

        # Python의 Figure 객체에도 변경 내용 저장
        for index, legend_name in enumerate(legend_names):
            if index < len(self.search_data_fig.data):
                self.search_data_fig.data[index].name = legend_name

        # 현재 QWebEngineView에 표시된 범례만 변경
        javascript_lines = [
            """
            (function() {
                const graphDiv = document.querySelector('.plotly-graph-div');

                if (!graphDiv || typeof Plotly === 'undefined') {
                    return false;
                }
            """
        ]

        for index, legend_name in enumerate(legend_names):
            escaped_name = self.escape_javascript_text(legend_name)

            javascript_lines.append(
                f"""
                if ({index} < graphDiv.data.length) {{
                    Plotly.restyle(
                        graphDiv,
                        {{name: '{escaped_name}'}},
                        [{index}]
                    );
                }}
                """
            )

        javascript_lines.append(
            """
                return true;
            })();
            """
        )

        javascript = "".join(javascript_lines)
        self.web_view.page().runJavaScript(javascript)

    
    # tab [데이터 관리] : [데이터조회] 조회자료가 NULL값일 경우 처리
    def convert_data_nullToNan(self, data):
        if str(data) == 'None':
            return np.NAN
        else:
            return float(data)
        
