    def get_dataset_ui_values(self):
        ui_data = {
            "targetText": self.txtBox_dsRef_targetPoint_id.text().strip(),
        }

        ui_data.update(self.get_dataset_reference_items())
        ui_data.update(self.get_dataset_column_selection())
        ui_data.update(self.get_dataset_period_values())
        ui_data.update(self.get_dataset_leadtime_values())
        ui_data.update(self.get_dataset_preprocessing_values())

        return ui_data

    # tab [데이터셋 생성]: 입력 선택/수집 - 레이어선택 (선택된 타겟/참조지점과 개수 라벨을 초기화)
    def dataset_on_select_layer(self, layer_name):
        layers = QgsProject.instance().mapLayersByName(layer_name)
        if layers:
            layer = layers[0]
            iface.setActiveLayer(layer)
            iface.mapCanvas().refresh()
            print(f"[Dataset Creation] Please select an object from {layer.name()}.")

            layer = iface.activeLayer()  
            canvas = iface.mapCanvas()

            if layer is None:
                QMessageBox.warning(self, tr(self.current_language, "title_dataset_creation"), tr(self.current_language, "msg_no_layer_selected"), QMessageBox.Ok) 
            
            else:
                select_tool = QgsMapToolIdentifyFeature(canvas, layer)
                canvas.setMapTool(select_tool)
                iface.actionSelect().trigger()       
    
