    def update_dataset_leadtime_controls(self):
        is_basic = self.rb_ds_leadtimeBasic.isChecked()
        is_timeseries = self.rb_ds_leadtimeTimeseries.isChecked()

        self.ckb_ds_leadtimeHarf.setEnabled(is_basic)
        self.ckb_ds_leadtime1h.setEnabled(is_basic)
        self.ckb_ds_leadtime2h.setEnabled(is_basic)
        self.ckb_ds_leadtime3h.setEnabled(is_basic)
        self.ckb_ds_leadtime4h.setEnabled(is_basic)
        self.ckb_ds_leadtime5h.setEnabled(is_basic)
        self.ckb_ds_leadtime6h.setEnabled(is_basic)

        self.cb_ds_leadtimeTarget.setEnabled(is_timeseries)
        self.cb_ds_leadtimeTerm.setEnabled(is_timeseries)
        self.cb_ds_leadtimeUnit.setEnabled(is_timeseries)

    # tab [데이터셋 생성]: 옵션 제어 - 리드타임 간격 옵션 항목 갱신
    def update_dataset_leadtime_term_options(self, index):
        self.cb_ds_leadtimeTerm.clear()

        if index == 0:
            for i in range(1, 7):
                self.cb_ds_leadtimeTerm.addItem(str(i))
            self.lbl_ds_leadtimeTerm.setText(tr(self.current_language, "label_hour_interval"))
        elif index == 1:
            for i in range(1, 7):
                self.cb_ds_leadtimeTerm.addItem(str(i * 10))
            self.lbl_ds_leadtimeTerm.setText(tr(self.current_language, "label_minute_interval"))
        else:
            self.lbl_ds_leadtimeTerm.setText("")

    # tab [데이터셋 생성]: 옵션 제어 - 무강우사상 관련 컨트롤 상태 갱신
    def update_dataset_no_rain_controls(self):
        is_checked = self.ckb_ds_preProcessing_noRain.isChecked()
        self.txtBox_ds_preProcessing_noRain.setEnabled(is_checked)
        self.ckb_ds_preProcessing_checkWL.setEnabled(is_checked)

    # tab [데이터셋 생성]: 옵션 제어 - No Rain 선택 상태에 따라 수위변화량 설정 컨트롤 활성화
    def update_dataset_no_rain_checkWL_controls(self):
        is_checked = self.ckb_ds_preProcessing_checkWL.isChecked()
