    ######################################################################################
    
    # tab [하천수위예측 모형제작] call:파라메터 초기화
    def init_makemodelParam(self):
        self.sp_dl_dropOutRate.setValue(0)
        self.sp_dl_sequenceLength.setValue(0)
        self.sp_dl_hiddenDim.setValue(0)
        self.sp_dl_sizeOfBatch.setValue(0)
        self.sp_dl_learningRate.setValue(0)
        self.sp_dl_interation.setValue(0)
        self.sp_dl_valudatuinSplit.setValue(0)
        self.sp_dl_trainingRate.setValue(1.0)
        self.sp_dl_testRate.setValue(1.0)
        self.sp_dl_hiddenLayer.setValue(0)
        self.txtBox_dl_units.clear()
        self.cb_dl_activationFunc.setCurrentText("relu")
        self.cb_dl_optimizeFunc.setCurrentText("adam")
        self.cb_dl_lossFunc.setCurrentText("mean_squared_error")

    # 문자열 값을 정수 또는 실수 자료형으로 자동 변환
    def auto_cast(self, value: str):
        try:
            # parsing 
            return ast.literal_eval(value)
        except (ValueError, SyntaxError):
            # original
            return value

    # tab [하천수위예측 모형제작] 파라메터(modelParam.txt) 불러오기 Button
    def LoadMakeModelParam(self):
        fileData, _ = QFileDialog.getOpenFileName(None, tr(self.current_language, "filedlg_open_modelparam_file"), '', 'txt file(modelParam*.txt)')
        # 선택된 파일이 없을때 리턴
        if fileData == '': return

        # control 초기화
        self.init_makemodelParam()                        

        modeldict_data = {}
        try:
            with open(fileData, "r", encoding="cp949") as file:
                for lineno, line in enumerate(file, 1):
                    try:
                        if ',' not in line:
                            continue  # 콤마 없는 라인은 무시

                        key, value = line.strip().split(',', 1)
                        key = key.strip()
                        value = value.strip()

                        if key == "watershed_with_target":
                            modeldict_data[key] = value
                        else:
                            try:
                                modeldict_data[key] = self.auto_cast(value)
                            except (ValueError, TypeError) as e:
                                # 변환 실패 시 None으로 처리하고 로그
                                print(f"[Model Creation] Failed to convert value of {key} at line {lineno}. : {value} ({e})")
                                modeldict_data[key] = None

                    except Exception as e:
                        # split 등에서 발생할 수 있는 다른 예외 처리
                        print(f"[Model Creation] Failed to process line {lineno}.: {line.strip()} ({e})")

        except (FileNotFoundError, UnicodeDecodeError) as e:
            print(f"[Model Creation] Failed to open file.: {fileData} ({e})")

        # key_value_check
        # 누락된 key는 메시지로 표시한다.
        # 누락된 항목이 있어도 불러오기를 중단하지 않고,
        # 파일에 존재하는 항목만 화면에 적용한다.

        model_keys = [
            "data_path",
            "save_path",
            "random_number",
            "model_name",
            "drop_out_rate",
            "seq_length",
            "hidden_dim",
            "size_of_batch",
            "learning_rate",
            "iterations",
            "patience_num",
            "training_rate",
            "test_start",
            "train_size",
            "test_size",
            "criteria_header",
            "criteria_wl",
            "Data_X_Column",
            "X_data_training_column_list",
            "watershed_with_target",
            "apply_realtime_Pred_WS",
            "realtime_Pred_WS_time",
            "Data_Y_Column",
            "Y_data_training_column_list",
            "data_dim",
            "output_dim",
            "lead_time",
            "Predict_time_index",
            "Predict_time_leadtime",
            "validation_rate",
            "hidden_layer_unit",
            "hidden_layer",
            "activation_func",
            "optimize_func",
            "loss_func",
            "Elapsed_time(sec)"
        ]

        # 파일에 없는 key 확인
        missing_keys = [
            key
            for key in model_keys
            if key not in modeldict_data
        ]

        # 누락된 key는 메시지만 표시하고 계속 불러온다.
        if missing_keys:
            QMessageBox.warning(
                self,
                tr(
                    self.current_language,
                    "title_model_creation"
                ),
                tr(
                    self.current_language,
                    "msg_f_check_contents_modelparameter_file_following_keys_missing"
                ).format(str(missing_keys)),
                QMessageBox.Ok
            )

            # 누락 key가 있어도 return하지 않는다.

        # key가 존재하고 변환된 값이 None이 아닌지 확인
        def has_model_value(key):
            return (
                key in modeldict_data
                and modeldict_data[key] is not None
            )
        # ============================================================
        # K-Fold 전용 파라미터 설정
        #
        # K-Fold 파라미터가 파일에 존재하는 경우에만 화면에 적용한다.
        # 일반 모델 파일에는 해당 항목이 없으므로 아무 작업도 하지 않는다.
        # ============================================================

        if has_model_value("K-fold parameter : k"):
            self.sp_load_dl_kfold_kk.setValue(
                int(modeldict_data["K-fold parameter : k"])
            )

        if has_model_value("K-fold parameter : repeat"):
            self.sp_load_dl_kfold_repeat.setValue(
                int(modeldict_data["K-fold parameter : repeat"])
            )

        # ============================================================
        # 모형제작 기본 파라미터 설정
        # ============================================================

        if has_model_value("drop_out_rate"):
            self.sp_dl_dropOutRate.setValue(
                float(modeldict_data["drop_out_rate"])
            )

        if has_model_value("seq_length"):
            self.sp_dl_sequenceLength.setValue(
                int(modeldict_data["seq_length"])
            )

        if has_model_value("hidden_dim"):
            self.sp_dl_hiddenDim.setValue(
                int(modeldict_data["hidden_dim"])
            )

        if has_model_value("size_of_batch"):
            self.sp_dl_sizeOfBatch.setValue(
                int(modeldict_data["size_of_batch"])
            )

        if has_model_value("learning_rate"):
            self.sp_dl_learningRate.setValue(
                float(modeldict_data["learning_rate"])
            )

        if has_model_value("iterations"):
            self.sp_dl_interation.setValue(
                int(modeldict_data["iterations"])
            )

        if has_model_value("patience_num"):
            self.sb_dl_patienceNum.setValue(
                int(modeldict_data["patience_num"])
            )

        if has_model_value("validation_rate"):
            self.sp_dl_valudatuinSplit.setValue(
                float(modeldict_data["validation_rate"])
            )

        if has_model_value("training_rate"):
            self.sp_dl_trainingRate.setValue(
                float(modeldict_data["training_rate"])
            )

        if has_model_value("hidden_layer"):
            self.sp_dl_hiddenLayer.setValue(
                int(modeldict_data["hidden_layer"])
            )

        if has_model_value("test_start"):
            self.sp_dl_testRate.setValue(
                float(modeldict_data["test_start"])
            )

        # ============================================================
        # 은닉층 unit 설정
        # ============================================================

        if has_model_value("hidden_layer_unit"):

            tmp_hidden_layer_unit = re.findall(
                r'\d+',
                str(modeldict_data["hidden_layer_unit"])
            )

            result_hidden_layer_unit = ', '.join(
                tmp_hidden_layer_unit
            )

            self.txtBox_dl_units.setText(
                result_hidden_layer_unit
            )

        # ============================================================
        # 활성화 함수, 최적화 함수, 손실 함수 설정
        # ============================================================

        if has_model_value("activation_func"):
            self.cb_dl_activationFunc.setCurrentText(
                str(modeldict_data["activation_func"])
            )

        if has_model_value("optimize_func"):
            self.cb_dl_optimizeFunc.setCurrentText(
                str(modeldict_data["optimize_func"])
            )

        if has_model_value("loss_func"):
            self.cb_dl_lossFunc.setCurrentText(
                str(modeldict_data["loss_func"])
            )

        # ============================================================
        # 기준 데이터 컬럼 설정
        # ============================================================

        if has_model_value("criteria_header"):

            criteria_header = modeldict_data["criteria_header"]

            # 단일 문자열인 경우
            if isinstance(criteria_header, str):
                qlinetext = criteria_header

            # 리스트 또는 튜플인 경우
            elif isinstance(criteria_header, (list, tuple)):
                qlinetext = ', '.join(
                    str(value)
                    for value in criteria_header
                )

            else:
                qlinetext = str(criteria_header)

            self.txtBox_dl_criteriaHeader.setText(
                qlinetext
            )

        # ============================================================
        # 실시간 예측 유역평균강우 설정
        # ============================================================

        if (
            self.ckb_dl_applyRealtimePredWS.isEnabled()
            and has_model_value("apply_realtime_Pred_WS")
        ):

            bPredws = modeldict_data[
                "apply_realtime_Pred_WS"
            ]

            # 문자열로 저장된 경우 bool 값으로 변환
            if isinstance(bPredws, str):
                bPredws = (
                    bPredws.strip().lower()
                    in ["true", "1", "yes", "y", "on"]
                )
            else:
                bPredws = bool(bPredws)

            self.ckb_dl_applyRealtimePredWS.setChecked(
                bPredws
            )

            # 실시간 예측 유역평균강우를 사용하는 경우에만
            # 예측시간을 설정한다.
            if (
                bPredws
                and has_model_value("realtime_Pred_WS_time")
            ):

                pred_hour = int(
                    modeldict_data["realtime_Pred_WS_time"]
                )

                if (
                    pred_hour > 0
                    and self.cb_dl_applyRealtimePredWsTime.count() > 0
                ):

                    index = (
                        self.cb_dl_applyRealtimePredWsTime.findText(
                            str(pred_hour)
                        )
                    )

                    if index > -1:
                        self.cb_dl_applyRealtimePredWsTime.setCurrentIndex(
                            index
                        )

        # ============================================================
        # 표준유역코드 설정
        # ============================================================

        if has_model_value("watershed_with_target"):
            self.txtBox_dl_watershedWithTarget.setText(
                str(modeldict_data["watershed_with_target"])
            )

        # ============================================================
        # 기준 수위 설정
        # ============================================================

        if has_model_value("criteria_wl"):

            criteria_wl = modeldict_data["criteria_wl"]

            # 단일 문자열 또는 숫자인 경우에도 처리
            if isinstance(criteria_wl, (list, tuple)):
                qline_text = ', '.join(
                    str(num)
                    for num in criteria_wl
                )
            else:
                qline_text = str(criteria_wl)

            origin_wl_text = (
                self.txtBox_dl_criteriaWL.text().strip()
            )

            current_text = origin_wl_text.replace(
                ", ",
                ","
            )

            new_text = qline_text.strip().replace(
                ", ",
                ","
            )

            # 현재 기준수위가 없는 경우 파일값 적용
            if not current_text:
                self.txtBox_dl_criteriaWL.setText(
                    qline_text
                )

            # 현재값과 파일값이 다른 경우 변경 여부 확인
            elif current_text != new_text:

                reply = QMessageBox.question(
                    self,
                    tr(
                        self.current_language,
                        "title_model_creation"
                    ),
                    tr(
                        self.current_language,
                        "msg_f_want_update_current_value_current_value_origin"
                    ).format(
                        origin_wl_text,
                        qline_text
                    ),
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No
                )

                if reply == QMessageBox.Yes:
                    self.txtBox_dl_criteriaWL.setText(
                        qline_text
                    )

            # 현재값과 파일값이 같은 경우 그대로 적용
            else:
                self.txtBox_dl_criteriaWL.setText(
                    qline_text
                )

    # tab [하천수위예측 모형제작] Save Path 설정 Button
    def SetMakeModelSavePath(self):
        path = QFileDialog.getExistingDirectory(self)
        if os.path.exists(path):
            self.txtBox_dl_saveParamPath.setText(path)
    
    # tab [하천수위예측 모형제작] ItemData All Select 설정 Checkbox
    def SetMakeModel_ItemDataSelect(self):
        bChecked = self.ckb_dl_itemdata_all.isChecked()        
        model_items = self.tbl_modelDatasetColumn.model()        
        if model_items is not None:
            for mIdx in range(model_items.rowCount()):                
                item = model_items.item(mIdx)                
                text = item.text()
                if text.startswith("Target_"):
                    item.setCheckState(True)
                else:
                    item.setCheckState(bChecked)

    # tab [하천수위예측 모형제작] Leadtime All Select 설정 Checkbox
    def SetMakeModel_LeadtimeSelect(self):
        bChecked = self.ckb_dl_leadtime_all.isChecked()        
        model_lead = self.tbl_modelDatasetLeadtime.model()        
        if model_lead is not None:
            for mIdx in range(model_lead.rowCount()):
                item = model_lead.item(mIdx)
                item.setCheckState(bChecked)

    # tab [하천수위예측 모형제작] call:모형제작에 필요한 입력자료 확인
    def checkInputParameter(self):

        # 1.데이터셋 파일이 설정되었는지,
        datafilepath = self.txtBox_dl_datasetFile.text()
        if datafilepath == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_select_dataset_file"), QMessageBox.Ok)
            return "None"

        # 1-1. 데이터셋에 Null값이 포함되었는지,
        #global isMakeModelDataNull
        if self.isMakeModelDataNull == True:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_dataset_file_contains_null_values"), QMessageBox.Ok)
            return "None"

        # 2.모형제작 저장경로(폴더) 설정되었는지,
        modelpath = self.txtBox_dl_saveParamPath.text()
        if modelpath == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_select_folder_save_model"), QMessageBox.Ok)
            return "None"

        # 3.모형제작 모델명 설정되었는지,
        modelname = self.txtBox_dl_modelName.text()
        if modelname == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_enter_model_name"), QMessageBox.Ok)
            return "None"

        # n.모델생성을 위한 모델(LSTM, GRU 등)이 선택되었는지? <---- 선택된 모델에 따라서, 체크해야할 항목이 다르다.
        selected_model = self.cb_makemodel_selectmodel.currentText().strip()
        model_info = self.get_model_env_info(model_name=selected_model)

        python_exe_path = model_info.get('python_path', '').strip()
        model_folder_path = model_info.get('model_path', '').strip()

        if not selected_model:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_select_model"), QMessageBox.Ok)
            return "None"

        if not python_exe_path:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_python_executable_path_selected_model_empty"), QMessageBox.Ok)
            return "None"

        if not model_folder_path:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_model_folder_path_selected_model_empty"), QMessageBox.Ok)
            return "None"

        # 4.Hidden Layer 입력항목이 제대로 작성되었는지,
        tmpHiddenUnits = self.txtBox_dl_units.text().split(',')
        for tmpNumber in tmpHiddenUnits:
            try:
                intValues = int(tmpNumber.strip())
            except ValueError:
                QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_check_hidden_layer_input_values_example_32_64"),
                                    QMessageBox.Ok)
                return "None"

        # 5.Hidden Layer갯수에 따라 HiddenLayerUnit이 동일갯수로 입력되었는지,
        hiddenlayerunit = self.txtBox_dl_units.text().split(',')
        if (len(hiddenlayerunit) > 0 and hiddenlayerunit[0] != '' and int(hiddenlayerunit[0]) > 0):
            hidden_layer_unit = [int(i) for i in hiddenlayerunit]
            hiddenlayercount = self.sp_dl_hiddenLayer.value()
            if hiddenlayercount != len(hidden_layer_unit):
                QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_enter_values_according_number_hidden_layers"), QMessageBox.Ok)
                return "None"
        else:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_enter_values_matching_number_hidden_layers"), QMessageBox.Ok)
            return "None"

        # 6.사용할 컬럼이 선택되었는지 체크하기!
        useCol_checked = False
        model_col = self.tbl_modelDatasetColumn.model()
        for mIdx in range(model_col.rowCount() - 1):
            item = model_col.item(mIdx + 1)
            if item.checkState():
                useCol_checked = True
                break
        if useCol_checked == False:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_select_data_columns_use_model_creation"), QMessageBox.Ok)
            return "None"

        # 7.사용할 leadtime이 설정되었는지,
        leadtime_checked = False
        model_lead = self.tbl_modelDatasetLeadtime.model()
        for mIdx in range(model_lead.rowCount()):
            item = model_lead.item(mIdx)
            if item.checkState():
                leadtime_checked = True
        if leadtime_checked == False:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_select_lead_time_column_use_model_creation"), QMessageBox.Ok)
            return "None"                
                            
        # 8.유역정보가 입력되었는지,
        watershed_code = self.txtBox_dl_watershedWithTarget.text()
        if watershed_code == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_enter_standard_watershed_code_information"), QMessageBox.Ok)
            return "None"
        
        # 9.유역정보가 데이터셋에 있는지,       
        watershed_info = False
        model_col = self.tbl_modelDatasetColumn.model()
        for mIdx in range(model_col.rowCount()): 

            item = model_col.item(mIdx)
            if item is None:
                continue

            # 체크되지 않은 컬럼은 확인하지 않음
            if int(item.checkState()) <= 0:
                continue

            col_text = item.text().strip()

            # 일반 유역평균강우 컬럼
            is_watershed_column = (
                col_text == f"WS_{watershed_code}"
            )

            # 예측 유역평균강우 컬럼
            # 예: Predict_WS3_1001, Predict_WS6_1001
            is_predict_watershed_column = (
                col_text.startswith("Predict_WS")
                and col_text.endswith(f"_{watershed_code}")
            )

            if is_watershed_column or is_predict_watershed_column:
                watershed_info = True
                break
        
        if watershed_info == False:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_standard_watershed_code_ws_information_missing_not_selected"), QMessageBox.Ok)
            return "None"
                        
        # 10. APPLY REALTIME PREDICT RAIN,
        bPredictRain = self.ckb_dl_applyRealtimePredWS.isChecked()
        if (bPredictRain):      
            # 9-1.predict_ws정보가 데이터셋에 있는지,
            watershed_rain_info = False
            model_col = self.tbl_modelDatasetColumn.model()
            for mIdx in range(model_col.rowCount()):
                item = model_col.item(mIdx)
                col_text = item.text()
                Predict_WS_hour =  int(self.cb_dl_applyRealtimePredWsTime.currentText())
                col_predictws = 'Predict_WS{}_'.format(Predict_WS_hour)
                col_text = col_text.replace(col_predictws, '')
                if ((col_text == watershed_code) and (int(item.checkState())>0)):
                    watershed_rain_info = True
                    break    
            if watershed_rain_info == False:
                QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_standard_watershed_code_predict_ws_information_applying_observed"), QMessageBox.Ok)
                return "None"
        
            # 9-2.예측강우 사용시 예측강우 폴더가 설정되어 있는지,
            predict_rain_path = self.txtBox_dash_obsPath.text().strip()        
            if predict_rain_path == "":
                QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_use_apply_realtime_predict_ws_set_observed_data"), QMessageBox.Ok)
                return "None"
            
        # 11. test_start가 1.0인지 확인,
        test_start_val = self.sp_dl_testRate.value()
        if test_start_val == 1.0:
            reply = QMessageBox.question(
                self,
                tr(self.current_language, "title_model_creation"),
                tr(self.current_language, "msg_f_no_test_data_set_want_proceed_anyway"),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )
            if reply == QMessageBox.Yes:
                return "OK"
            else:
                self.sp_dl_testRate.setFocus()
                return "None"
        elif test_start_val > 1.0:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_reset_test_data"), QMessageBox.Ok)
            self.sp_dl_testRate.setFocus()
            return "None"
        else:
            return "OK"
            
    # [하천수위예측모형제작] Training_rate(sp_dl_trainingRate) == Test_start(sp_dl_testRate)        
    def ChangedValue_TrainingTestValue(self):
        val = self.sp_dl_trainingRate.value()
        self.sp_dl_testRate.setValue(val)
    
    # [하천수위예측모형제작] 모델선택에 따른 경로확인 및 최적화창 popup
    def makemodel_optimization(self):
        selected_model = self.cb_makemodel_selectmodel.currentText().strip()
        model_info = self.get_model_env_info(model_name=selected_model)

        python_exe_path = model_info.get('python_path', '').strip()
        model_folder_path = model_info.get('model_path', '').strip()

        bayesian_py_path = os.path.join(self.program_path, 'bayesian.py')
        if not os.path.isfile(bayesian_py_path):
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_model_optimization"),
                tr(self.current_language, "msg_f_bayesian_py_file_not_found_bayesian_py").format(bayesian_py_path),
                QMessageBox.Ok
            )
            return
        
        #####################################################################

         # 모델 결과 저장 폴더
        modelpath = self.txtBox_dl_saveParamPath.text().strip()
        modelname = self.txtBox_dl_modelName.text().strip()

        saveReportPath = os.path.join(
            modelpath,
            modelname
        )

        # 기존 Bayesian Optimization 결과 파일
        best_params_path = os.path.join(
            saveReportPath,
            "best_params.csv"
        )

        trials_path = os.path.join(
            saveReportPath,
            "optimization_trials.csv"
        )

        existing_optimization_files = [
            file_path
            for file_path in [
                best_params_path,
                trials_path
            ]
            if os.path.isfile(file_path)
        ]

        # 기존 최적화 결과가 하나라도 있으면 재실행 여부 확인
        if existing_optimization_files:
            reply = QMessageBox.question(
                self,
                tr(
                    self.current_language,
                    "title_model_optimization"
                ),
                tr(
                    self.current_language,
                    "msg_optimization_files_already_exist_run_again"
                ),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No
            )

            # 다시 수행하지 않으면 종료
            if reply != QMessageBox.Yes:
                return

            # 다시 수행하면 기존 최적화 결과 파일 삭제
            delete_errors = []

            for file_path in existing_optimization_files:
                try:
                    os.remove(file_path)
                except Exception as e:
                    delete_errors.append(
                        f"{file_path}\n{e}"
                    )

            # 삭제에 실패하면 최적화 수행 중단
            if delete_errors:
                QMessageBox.critical(
                    self,
                    tr(
                        self.current_language,
                        "title_model_optimization"
                    ),
                    tr(
                        self.current_language,
                        "msg_failed_delete_existing_optimization_files"
                    ).format(
                        "\n\n".join(delete_errors)
                    ),
                    QMessageBox.Ok
                )
                return

        #####################################################################

        # check_values 

        # 1.데이터셋 파일이 설정되었는지,
        datafilepath = self.txtBox_dl_datasetFile.text()
        if datafilepath == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_optimization"), tr(self.current_language, "msg_select_dataset_file"), QMessageBox.Ok)
            return "None"

        # 1-1. 데이터셋에 Null값이 포함되었는지,
        if self.isMakeModelDataNull == True:
            QMessageBox.warning(self, tr(self.current_language, "title_model_optimization"), tr(self.current_language, "msg_dataset_file_contains_null_values"), QMessageBox.Ok)
            return "None"

        # 2.모형제작 저장경로(폴더) 설정되었는지,
        modelpath = self.txtBox_dl_saveParamPath.text()
        if modelpath == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_optimization"), tr(self.current_language, "msg_select_folder_save_model"), QMessageBox.Ok)
            return "None"

        # 3.모형제작 모델명 설정되었는지,
        modelname = self.txtBox_dl_modelName.text()
        if modelname == "":
            QMessageBox.warning(self, tr(self.current_language, "title_model_optimization"), tr(self.current_language, "msg_enter_model_name"), QMessageBox.Ok)
            return "None"       
       
        # 사용할 컬럼이 선택되었는지 체크하기!
        useCol_checked = False
        model_col = self.tbl_modelDatasetColumn.model()
        for mIdx in range(model_col.rowCount() - 1):
            item = model_col.item(mIdx + 1)
            if item.checkState():
                useCol_checked = True
                break
        if useCol_checked == False:
            QMessageBox.warning(self, tr(self.current_language, "title_model_optimization"), tr(self.current_language, "msg_select_data_columns_use_model_creation"), QMessageBox.Ok)
            return "None"

        # 사용할 leadtime이 설정되었는지,
        leadtime_checked = False
        model_lead = self.tbl_modelDatasetLeadtime.model()
        for mIdx in range(model_lead.rowCount()):
            item = model_lead.item(mIdx)
            if item.checkState():
                leadtime_checked = True
        if leadtime_checked == False:
            QMessageBox.warning(self, tr(self.current_language, "title_model_optimization"), tr(self.current_language, "msg_select_lead_time_column_use_model_creation"), QMessageBox.Ok)
            return "None"               
            
        #####################################################################

        if not selected_model:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_select_model"), QMessageBox.Ok)
            return

        if not python_exe_path:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_python_executable_path_selected_model_empty"), QMessageBox.Ok)
            return

        if not model_folder_path:
            QMessageBox.warning(self, tr(self.current_language, "title_model_creation"), tr(self.current_language, "msg_model_folder_path_selected_model_empty"), QMessageBox.Ok)
            return

        schema = self.get_makemodel_optimization_schema(selected_model)
        current_values = self._get_model_specific_optimization_values(selected_model)

        dlg = BayesianOptimizationDialog(
            self,
            model_name=selected_model,
            schema=schema,
            current_values=current_values,
            lang=self.current_language
        )
        if dlg.exec_() != QDialog.Accepted:
            return

        if not hasattr(self, 'makemodel_optimization_values') or not isinstance(self.makemodel_optimization_values, dict):
            self.makemodel_optimization_values = {}

        self.makemodel_optimization_values[selected_model] = dlg.get_result()

        result = self.makemodel_optimization_values[selected_model]

        if self._run_bayesian_optimization_txt(
            selected_model=selected_model,
            python_exe_path=python_exe_path,
            model_folder_path=model_folder_path,
            optimization_values=result,
            schema=schema
        ) == "None":
            return

        return

    # [하천수위예측모형제작] Bayesian Optimization 입력 txt 생성
    def _create_bayesian_param_txt(self, selected_model, optimization_values, param_path):
        """
        bayesian.py에 전달할 optimization_param.txt 생성.
        현재 방식은 JSON이 아니라 key,value txt 방식만 사용한다.
        """

        datafilepath = self.txtBox_dl_datasetFile.text().strip()
        modelpath = self.txtBox_dl_saveParamPath.text().strip()
        modelname = self.txtBox_dl_modelName.text().strip()

        save_model_path = os.path.join(modelpath, modelname)
        save_report_path = os.path.join(save_model_path, '')

        # MakeModel()과 동일한 방식으로 X/Y 컬럼 수집
        Data_X_Column = []
        Data_Y_Column = []

        model_col = self.tbl_modelDatasetColumn.model()
        model_col_row_count = model_col.rowCount()

        for mIdx in range(model_col_row_count):
            item = model_col.item(mIdx)
            if item is not None and int(item.checkState()) > 0:
                Data_X_Column.append(mIdx + 1)

        model_lead = self.tbl_modelDatasetLeadtime.model()

        for mIdx in range(model_lead.rowCount()):
            item = model_lead.item(mIdx)
            if item is not None and int(item.checkState()) > 0:
                Data_Y_Column.append(model_col_row_count + mIdx + 1)        

        # 다이얼로그에서 선택한 최적화 방식
        search_mode = optimization_values.get('search_mode', 'range')

        # 다이얼로그 get_result()에서 반환한 리스트값을 가져온다.
        seq_length_values = optimization_values.get(
            'sequence_length_values',
            [12, 18, 24, 36, 48, 72]
        )

        dropout_rate_values = optimization_values.get(
            'dropout_rate_values',
            [0.0, 0.05, 0.1, 0.2, 0.3]
        )

        hidden_neuron_values = optimization_values.get(
            'hidden_neuron_values',
            [16, 32, 64]
        )

        number_of_layer_values = optimization_values.get(
            'number_of_layer_values',
            [2, 3, 4]
        )

        batch_size_values = optimization_values.get(
            'batch_size_values',
            [16, 32, 40, 48]
        )

        lines = [
            f"bayesian_epoch,{optimization_values.get('bayesian_epoch', 50)}",
            f"testing_epoch,{optimization_values.get('testing_epoch', 10)}",

            # 최적화 방식 : range 또는 list
            f"search_mode,{search_mode}",

            # 범위 방식(Min / Max) 값
            f"seq_length_min,{optimization_values.get('sequence_length_min', 24)}",
            f"seq_length_max,{optimization_values.get('sequence_length_max', 36)}",

            f"dropout_rate_min,{optimization_values.get('dropout_rate_min', 0.05)}",
            f"dropout_rate_max,{optimization_values.get('dropout_rate_max', 0.3)}",

            f"hidden_neuron_min,{optimization_values.get('hidden_neuron_min', 16)}",
            f"hidden_neuron_max,{optimization_values.get('hidden_neuron_max', 32)}",

            f"number_of_layer_min,{optimization_values.get('number_of_layer_min', 2)}",
            f"number_of_layer_max,{optimization_values.get('number_of_layer_max', 4)}",

            f"batch_size_min,{optimization_values.get('batch_size_min', 16)}",
            f"batch_size_max,{optimization_values.get('batch_size_max', 48)}",

            # 리스트 방식(List) 후보값
            f"seq_length_list,{json.dumps(seq_length_values)}",
            f"dropout_rate_list,{json.dumps(dropout_rate_values)}",
            f"hidden_neuron_list,{json.dumps(hidden_neuron_values)}",
            f"number_of_layer_list,{json.dumps(number_of_layer_values)}",
            f"batch_size_list,{json.dumps(batch_size_values)}",

            f"data_path,{datafilepath}",
            f"save_path,{save_report_path}",
            f"model_name,{modelname}",

            f"training_rate,{self.sp_dl_trainingRate.value()}",

            f"Data_X_Column,{Data_X_Column}",
            f"Data_Y_Column,{Data_Y_Column}",

            f"hidden_dim,{self.sp_dl_hiddenDim.value()}",

            f"validation_rate,{self.sp_dl_valudatuinSplit.value()}",
            f"activation_func,{self.cb_dl_activationFunc.currentText().strip()}",
            f"optimize_func,{self.cb_dl_optimizeFunc.currentText().strip()}",
            f"loss_func,{self.cb_dl_lossFunc.currentText().strip()}",
        ]

        with open(param_path, "w", encoding="cp949") as f:
            f.write("\n".join(lines) + "\n")

        return param_path


    # [하천수위예측모형제작] Bayesian Optimization 실행
    def _run_bayesian_optimization_txt(self, selected_model, python_exe_path, model_folder_path, optimization_values, schema):
        """
        현재 bayesian.py 실행 방식:
        argv[1] = optimization_param.txt
        argv[2] = python_exe_path
        argv[3] = predict_data_path
        """

        try:
            # MakeModel과 동일하게 기본 입력값 검사
            if not python_exe_path or not os.path.isfile(python_exe_path):
                QMessageBox.warning(
                    self,
                    tr(self.current_language, "title_model_optimization"),
                    tr(self.current_language, "msg_python_executable_path_invalid"),
                    QMessageBox.Ok
                )
                return "None"

            if not model_folder_path or not os.path.isdir(model_folder_path):
                QMessageBox.warning(
                    self,
                    tr(self.current_language, "title_model_optimization"),
                    tr(self.current_language, "msg_model_folder_path_invalid"),
                    QMessageBox.Ok
                )
                return "None"

            script_path = os.path.join(self.program_path, 'bayesian.py')
            if not os.path.isfile(script_path):
                QMessageBox.warning(
                    self,
                    tr(self.current_language, "title_model_optimization"),
                    tr(self.current_language, "msg_f_bayesian_py_not_found_script_path").format(script_path),
                    QMessageBox.Ok
                )
                return "None"

            modelpath = self.txtBox_dl_saveParamPath.text().strip()
            modelname = self.txtBox_dl_modelName.text().strip()
            save_report_path = os.path.join(modelpath, modelname, '')

            os.makedirs(save_report_path, exist_ok=True)

            param_path = os.path.join(save_report_path, "optimization_param.txt")

            self._create_bayesian_param_txt(
                selected_model=selected_model,
                optimization_values=optimization_values,
                param_path=param_path
            )

            env = os.environ.copy()
            env.pop("PYTHONPATH", None)
            env.pop("PYTHONHOME", None)

            realtime_rain_path = self.txtBox_dash_obsPath.text().strip()

            self.result_bayesian = subprocess.Popen(
                [
                    python_exe_path,
                    script_path,
                    param_path,
                    python_exe_path,
                    realtime_rain_path
                ],
                env=env,
                creationflags=subprocess.CREATE_NEW_CONSOLE
            )

            self._check_bayesian_optimization_finished_txt(save_report_path)

            return "OK"

        except Exception as e:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_model_optimization"),
                tr(self.current_language, "msg_f_failed_start_bayesian_optimization_e").format(e),
                QMessageBox.Ok
            )
            return "None"

    # [하천수위예측모형제작] Bayesian Optimization 보존 대상 파일 목록 반환
    def _get_bayesian_optimization_artifact_names(self):
        """
        Bayesian Optimization 결과 중 최종 모델 폴더에 보존할 파일 목록.

        주의:
        - X_scaler.pkl, Y_scaler.pkl은 제외한다.
        - 모델 생성 시 makemodel.py가 최종 scaler를 새로 생성하므로,
          Bayesian 단계의 scaler를 복원하면 최종 모델 scaler를 덮어쓸 수 있다.
        """
        return [
            "best_params.csv",
            "optimization_trials.csv",
        ]


    # [하천수위예측모형제작] 경로 비교용 정규화
    def _normalize_path_for_compare(self, path):
        try:
            return os.path.normcase(os.path.abspath(str(path).strip()))
        except Exception:
            return str(path).strip()


    # [하천수위예측모형제작] Bayesian Optimization 임시 보관 폴더 초기화
    def _clear_bayesian_optimization_cache(self):
        cache_dir = getattr(self, "bayesian_optimization_cache_dir", "")

        if cache_dir and os.path.isdir(cache_dir):
            try:
                shutil.rmtree(cache_dir)
            except Exception as e:
                print(f"[Model Optimization] Failed to remove Bayesian cache folder: {e}")

        self.bayesian_optimization_cache_dir = ''
        self.bayesian_optimization_cached_files = []
        self.bayesian_optimization_source_path = ''


    # [하천수위예측모형제작] Bayesian Optimization 결과 파일 임시 보관
    def _cache_bayesian_optimization_outputs(self, source_folder):
        """
        Bayesian Optimization 완료 직후 결과 파일을 임시 폴더로 복사한다.
        모델 생성 시작 시 결과 폴더가 초기화되어도 이 임시 폴더의 파일은 유지된다.
        """
        source_folder = str(source_folder).strip()

        if not source_folder or not os.path.isdir(source_folder):
            return False, f"Source folder does not exist: {source_folder}"

        self._clear_bayesian_optimization_cache()

        try:
            cache_dir = tempfile.mkdtemp(prefix="kict_bayesian_optimization_")
        except Exception as e:
            return False, f"Failed to create temporary cache folder: {e}"

        copied_files = []

        for file_name in self._get_bayesian_optimization_artifact_names():
            src = os.path.join(source_folder, file_name)
            dst = os.path.join(cache_dir, file_name)

            if not os.path.isfile(src):
                continue

            try:
                shutil.copy2(src, dst)
                copied_files.append(file_name)
            except Exception as e:
                print(f"[Model Optimization] Failed to cache {file_name}: {e}")

        self.bayesian_optimization_cache_dir = cache_dir
        self.bayesian_optimization_cached_files = copied_files
        self.bayesian_optimization_source_path = source_folder

        if not copied_files:
            return False, "No Bayesian Optimization files were cached."

        print("[Model Optimization] Bayesian Optimization files were cached:")
        for file_name in copied_files:
            print(f" - {file_name}")

        return True, cache_dir


    # [하천수위예측모형제작] Bayesian Optimization 결과 파일 최종 모델 폴더에 복원
    def _restore_bayesian_optimization_outputs(self, model_save_folder):
        """
        모델 생성 완료 후 임시 보관한 Bayesian Optimization 결과를
        최종 모델 폴더/bayesian_optimization 하위 폴더에 저장한다.

        안전장치:
        - Bayesian Optimization을 실행했던 폴더와 현재 모델 생성 폴더가 같을 때만 복원한다.
        - 다른 모델/다른 저장경로에 이전 최적화 결과가 섞이는 것을 방지한다.
        """
        model_save_folder = str(model_save_folder).strip()
        cache_dir = getattr(self, "bayesian_optimization_cache_dir", "")
        cached_files = getattr(self, "bayesian_optimization_cached_files", [])
        source_path = getattr(self, "bayesian_optimization_source_path", "")

        if not model_save_folder:
            return False, "Model save folder is empty."

        if not cache_dir or not os.path.isdir(cache_dir):
            return False, "No cached Bayesian Optimization files."

        if not cached_files:
            return False, "Cached Bayesian Optimization file list is empty."

        if source_path:
            src_norm = self._normalize_path_for_compare(source_path)
            dst_norm = self._normalize_path_for_compare(model_save_folder)

            if src_norm != dst_norm:
                return False, (
                    "Cached Bayesian Optimization folder is different from current model folder. "
                    "Restore skipped to avoid mixing results."
                )        
        
        dst_folder = model_save_folder

        if not os.path.isdir(dst_folder):
            return False, (
                f"Model save folder does not exist: {dst_folder}"
            )

        copied_files = []

        for file_name in cached_files:
            src = os.path.join(cache_dir, file_name)
            dst = os.path.join(dst_folder, file_name)

            if not os.path.isfile(src):
                continue

            try:
                shutil.copy2(src, dst)
                copied_files.append(file_name)
            except Exception as e:
                print(f"[Model Optimization] Failed to restore {file_name}: {e}")

        if copied_files:
            print("[Model Optimization] Bayesian Optimization files were restored:")
            print(dst_folder)
            for file_name in copied_files:
                print(f" - {file_name}")

            # 복원 완료 후 임시 캐시 삭제
            self._clear_bayesian_optimization_cache()

            return True, dst_folder

        return False, "No Bayesian Optimization files were restored."
    
    # [하천수위예측모형제작] Bayesian Optimization 완료 확인
    def _check_bayesian_optimization_finished_txt(self, save_report_path):
        if not hasattr(self, "result_bayesian") or self.result_bayesian is None:
            return

        if self.result_bayesian.poll() is None:
            QTimer.singleShot(
                1000,
                lambda: self._check_bayesian_optimization_finished_txt(save_report_path)
            )
            return

        exit_code = self.result_bayesian.returncode
        if exit_code != 0:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_model_optimization"),
                tr(self.current_language, "msg_bayesian_optimization_failed_exit_code").format(exit_code),
                QMessageBox.Ok
            )
            return

        best_params_path = os.path.join(save_report_path, "best_params.csv")
        trials_path = os.path.join(save_report_path, "optimization_trials.csv")

        if not os.path.isfile(best_params_path):
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_model_optimization"),
                tr(self.current_language, "msg_f_best_params_csv_not_found_best_params").format(best_params_path),
                QMessageBox.Ok
            )
            return

        if not os.path.isfile(trials_path):
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_model_optimization"),
                tr(self.current_language, "msg_f_optimization_trials_csv_not_found_trials_path").format(trials_path),
                QMessageBox.Ok
            )
            return

        # Bayesian Optimization 결과 파일을 모델 생성 전 임시 보관한다.
        # 이후 모델 생성 과정에서 save_report_path가 초기화되어도 결과 파일을 복원할 수 있다.
        cache_ok, cache_msg = self._cache_bayesian_optimization_outputs(save_report_path)
        if not cache_ok:
            print(f"[Model Optimization] Bayesian Optimization cache warning: {cache_msg}")

        try:
            best_params_df = pd.read_csv(best_params_path)

            if best_params_df.empty:
                QMessageBox.warning(
                    self,
                    tr(self.current_language, "title_model_optimization"),
                    tr(self.current_language, "msg_f_best_params_csv_empty_best_params_path").format(best_params_path),
                    QMessageBox.Ok
                )
                return

            best_params = best_params_df.iloc[0].to_dict()

            summary = self._build_bayesian_best_params_summary(
                best_params=best_params,
                best_params_path=best_params_path,
                trials_path=trials_path
            )

            reply = QMessageBox.question(
                self,
                tr(self.current_language, "title_model_optimization"),
                summary,
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.Yes
            )

            if reply == QMessageBox.Yes:
                self._apply_bayesian_best_params_to_controls(best_params)
                QMessageBox.information(
                    self,
                    tr(self.current_language, "title_model_optimization"),
                    tr(self.current_language, "msg_optimal_parameters_been_applied_model_creation_controls"),
                    QMessageBox.Ok
                )
            else:
                # 최적화 결과를 컨트롤에 반영하지 않으면 결과 파일 삭제
                delete_targets = [
                    best_params_path,
                    trials_path,
                ]

                delete_errors = []

                for file_path in delete_targets:
                    try:
                        if file_path and os.path.isfile(file_path):
                            os.remove(file_path)
                    except Exception as e:
                        delete_errors.append(
                            f"{file_path}\n{e}"
                        )

                if delete_errors:
                    QMessageBox.warning(
                        self,
                        tr(self.current_language, "title_model_optimization"),
                        "Failed to delete optimization result files.\n\n"
                        + "\n\n".join(delete_errors),
                        QMessageBox.Ok
                    )
                else:
                    QMessageBox.information(
                        self,
                        tr(self.current_language, "title_model_optimization"),
                        tr(
                            self.current_language,
                            "msg_optimal_parameters_not_applied_files_deleted"
                        ),
                        QMessageBox.Ok
                    )


        except Exception as e:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_model_optimization"),
                tr(self.current_language, "msg_f_failed_read_apply_best_params_csv_e").format(e),
                QMessageBox.Ok
            )

    # [하천수위예측모형제작] Bayesian Optimization 최적 파라미터 요약문 생성
    def _build_bayesian_best_params_summary(self, best_params, best_params_path, trials_path):
        """
        best_params.csv의 최적 파라미터를 사용자 확인용 메시지로 구성한다.
        """

        def _fmt(value):
            try:
                if pd.isna(value):
                    return ''
            except Exception:
                pass

            try:
                if isinstance(value, float):
                    return f"{value:.6g}"
            except Exception:
                pass

            return str(value)

        seq_length = best_params.get('seq_length', '')
        drop_out_rate = best_params.get('drop_out_rate', '')
        n_layers = best_params.get('number_of_layers', '')
        batch_size = best_params.get('batch_size', '')
        best_val_loss = best_params.get('best_val_loss', '')

        neuron_items = []
        for key in sorted(best_params.keys()):
            if str(key).startswith('hidden_neuron_L'):
                neuron_items.append(f"{key}: {_fmt(best_params.get(key))}")

        neuron_text = "\n".join(neuron_items) if neuron_items else "None"


        summary = (
            tr(self.current_language, "msg_optimal_result_complete") +
            "[Best Parameters]\n"
            f"- Sequence Length : {_fmt(seq_length)}\n"
            f"- Dropout Rate    : {_fmt(drop_out_rate)}\n"
            f"- Hidden Layers   : {_fmt(n_layers)}\n"
            f"- Batch Size      : {_fmt(batch_size)}\n"
            f"- Best Val Loss   : {_fmt(best_val_loss)}\n\n"
            "[Hidden Neurons]\n"
            f"{neuron_text}\n\n"
            "[Result Files]\n"
            f"best_params.csv:\n{best_params_path}\n\n"
            f"optimization_trials.csv:\n{trials_path}\n\n"
            +tr(self.current_language, "msg_optimal_result_creation_controls") 
        )

        return summary


    # [하천수위예측모형제작] Bayesian Optimization 최적 파라미터를 화면 컨트롤에 반영
    def _apply_bayesian_best_params_to_controls(self, best_params):
        """
        best_params.csv의 최적 파라미터를 하천수위예측모형제작 화면 컨트롤에 반영한다.

        주의:
        - bayesian.py의 hidden_dim은 LSTM/GRU unit 크기가 아니라 레이어 개수로 사용 중이다.
        - 따라서 sp_dl_hiddenDim이 아니라 sp_dl_hiddenLayer에 반영한다.
        - hidden_neuron_L1, hidden_neuron_L2... 값은 txtBox_dl_units에 리스트 형태로 반영한다.
        """

        def _to_int(value, default=None):
            try:
                if pd.isna(value):
                    return default
            except Exception:
                pass

            try:
                return int(float(value))
            except Exception:
                return default

        def _to_float(value, default=None):
            try:
                if pd.isna(value):
                    return default
            except Exception:
                pass

            try:
                return float(value)
            except Exception:
                return default

        seq_length = _to_int(best_params.get('seq_length'), None)
        drop_out_rate = _to_float(best_params.get('drop_out_rate'), None)
        n_layers = _to_int(best_params.get('number_of_layers'), None)
        batch_size = _to_int(best_params.get('batch_size'), None)

        # Sequence Length
        if seq_length is not None and hasattr(self, 'sp_dl_sequenceLength'):
            self.sp_dl_sequenceLength.setValue(seq_length)

        # Dropout Rate
        if drop_out_rate is not None and hasattr(self, 'sp_dl_dropOutRate'):
            self.sp_dl_dropOutRate.setValue(drop_out_rate)

        # Batch Size
        if batch_size is not None and hasattr(self, 'sp_dl_sizeOfBatch'):
            self.sp_dl_sizeOfBatch.setValue(batch_size)

        # Hidden Layer 개수
        if n_layers is not None and hasattr(self, 'sp_dl_hiddenLayer'):
            self.sp_dl_hiddenLayer.setValue(n_layers)

        # Hidden Neuron 리스트 구성
        hidden_neuron_units = []

        if n_layers is not None:
            for i in range(1, n_layers + 1):
                key = f'hidden_neuron_L{i}'
                if key in best_params:
                    neuron_value = _to_int(best_params.get(key), None)
                    if neuron_value is not None:
                        hidden_neuron_units.append(neuron_value)

        # txtBox_dl_units에 [16, 32, ...] 형태로 반영
        if hidden_neuron_units and hasattr(self, 'txtBox_dl_units'):
            #self.txtBox_dl_units.setText(str(hidden_neuron_units))
            self.txtBox_dl_units.setText(", ".join(map(str, hidden_neuron_units)))
    
    # [하천수위예측모형제작] 모델별 최적화 입력 스키마 조회
