    # [Dashboard] CSV 캐시 키 생성을 위해 kwargs 값을 hash 가능한 형태로 변환
    def _make_hashable_cache_value(self, value):
        if isinstance(value, dict):
            return tuple(sorted((k, self._make_hashable_cache_value(v)) for k, v in value.items()))
        elif isinstance(value, (list, tuple)):
            return tuple(self._make_hashable_cache_value(v) for v in value)
        elif isinstance(value, set):
            return tuple(sorted(self._make_hashable_cache_value(v) for v in value))
        return value

    # [Dashboard] 동일 CSV 파일의 반복 read_csv를 줄이기 위해 옵션별로 캐시하여 반환
    def _read_csv_cached(self, file_path, **kwargs):
        if not file_path:
            raise ValueError("file_path is empty.")

        cache_key = (
            os.path.normpath(file_path),
            tuple(sorted((k, self._make_hashable_cache_value(v)) for k, v in kwargs.items()))
        )

        if cache_key not in self._csv_cache:
            self._csv_cache[cache_key] = pd.read_csv(file_path, **kwargs)

        return self._csv_cache[cache_key].copy()

    # [Dashboard] CSV 캐시 초기화 : 연도/권역/관측소 변경 시 Dashboard CSV 캐시를 초기화
    def _clear_dashboard_cache(self):
        self._csv_cache.clear()

    # [Dashboard] 그래프 이미지 저장 공통 처리 : Dashboard Figure 저장 다이얼로그를 공통 처리
    def _save_dashboard_figure(self, fig, dialog_title, default_filename):
        if fig is None:
            QMessageBox.warning(
                self,
                tr(self.current_language, "title_dashboard"),
                tr(self.current_language, "msg_there_no_graph_save"),
                QMessageBox.Ok
            )
            return

        file_path, _ = QFileDialog.getSaveFileName(
            self,
            dialog_title,
            default_filename,
            "PNG(*.png);;JPEG(*.jpg);;All(*.*)"
        )

        if file_path:
            fig.savefig(file_path, dpi=500)

    # [Dashboard] 콤보박스 인덱스 이동 공통 처리 : 콤보박스 현재 인덱스를 step만큼 이동
    def _move_combo_index(self, combo, step):
        if combo is None:
            return

        item_cnt = combo.count()
        if item_cnt <= 0:
            return

        cur_idx = combo.currentIndex()
        if cur_idx < 0:
            cur_idx = 0

        new_idx = cur_idx + step

        if new_idx < 0:
            new_idx = 0
        elif new_idx >= item_cnt:
            new_idx = item_cnt - 1

        if new_idx != cur_idx:
            combo.setCurrentIndex(new_idx)
    
    # ESC_KEY_EVENT
    def keyPressEvent(self, event):
        # ESC 또는 Enter 키를 눌렀을 때 아무 동작도 하지 않음
        if event.key() == Qt.Key_Escape or event.key() == Qt.Key_Return:
            event.ignore()  # 키 이벤트를 무시하여 기본 동작을 방지
        else:
            super().keyPressEvent(event)

    # [Initialize_control]
    def chart_initialize(self, fig, ax, canvas):
        fig.clf()
        ax = fig.add_subplot(111)
        fig.tight_layout()
        fig.subplots_adjust(left=0.1, right=0.95, top=0.9, bottom=0.2)

        x_labels_cnt = []
        x_labels_name = []
        # draw_reference_graphs
        ax.set_xticks(x_labels_cnt)
        ax.set_xticklabels(x_labels_name, size=6)     
        for tl in ax.yaxis.get_majorticklabels():
            tl.set_fontsize(6)
        ax.legend(prop={'size': 8})
        canvas.draw()

